def todoist_task_create(connection_id, content, description=None, project_id=None, section_id=None, parent_task_id=None, priority=None, due_string=None, due_date=None, due_timezone=None, deadline_at=None, label_ids=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0360000" if __import__("os").path.isdir("./environment_mix/0360000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(val, field):
        if val is None:
            return None, None
        if not isinstance(val, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 datetime string")
        s = val.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat(), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 datetime string")

    def _is_ulid_prefixed(x, pref):
        if not isinstance(x, str):
            return False
        return re.match(r"^" + re.escape(pref) + r"_[0-9A-HJKMNP-TV-Z]{18,}$", x) is not None

    def _sanitize_params():
        # Never store secrets; none are passed here. Keep small.
        return {
            "connection_id": connection_id,
            "content": content if isinstance(content, str) else None,
            "description": description if isinstance(description, str) else None,
            "project_id": project_id,
            "section_id": section_id,
            "parent_task_id": parent_task_id,
            "priority": priority,
            "due_string": due_string if isinstance(due_string, str) else None,
            "due_date": due_date if isinstance(due_date, str) else None,
            "due_timezone": due_timezone if isinstance(due_timezone, str) else None,
            "deadline_at": deadline_at if isinstance(deadline_at, str) else None,
            "label_ids": label_ids if isinstance(label_ids, list) else None,
        }

    def _ulid():
        # 26-char Crockford Base32 ULID
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        b = ms.to_bytes(6, "big") + secrets.token_bytes(10)
        # encode 128 bits to 26 chars
        n = int.from_bytes(b, "big")
        out = []
        for _ in range(26):
            n, r = divmod(n, 32)
            out.append(alphabet[r])
        return "".join(reversed(out))

    def _new_id(prefix):
        return f"{prefix}_{_ulid()}"

    def _record_run(status, http_status=None, error_code=None, error_message=None, connection_row=None):
        runs = _load("todoist_tool_runs.json")
        now = _now()
        dur = int((time.time() - start) * 1000)
        cid = connection_id if isinstance(connection_id, str) else (connection_row["id"] if connection_row else None)
        run = {
            "id": _new_id("tdrun"),
            "connection_id": cid if cid else "unknown",
            "tool_name": "todoist_task_create",
            "request_params": _sanitize_params(),
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": dur,
            "assertions": None,
            "created_at": now,
            "updated_at": now,
        }
        runs.append(run)
        _save("todoist_tool_runs.json", runs)

    # ---- Validation ----
    if not _is_ulid_prefixed(connection_id, "tdc"):
        _record_run("failed", error_code="VALIDATION_ERROR", error_message="connection_id is invalid")
        return _err("VALIDATION_ERROR", "connection_id is invalid")

    if not isinstance(content, str) or len(content.strip()) < 1 or len(content) > 500:
        _record_run("failed", error_code="VALIDATION_ERROR", error_message="content must be a non-empty string (1..500)")
        return _err("VALIDATION_ERROR", "content must be a non-empty string (1..500)")

    if description is not None and not isinstance(description, str):
        _record_run("failed", error_code="VALIDATION_ERROR", error_message="description must be a string")
        return _err("VALIDATION_ERROR", "description must be a string")

    if priority is None:
        priority = 1
    if not isinstance(priority, int) or priority not in (1, 2, 3, 4):
        _record_run("failed", error_code="VALIDATION_ERROR", error_message="priority must be one of 1,2,3,4")
        return _err("VALIDATION_ERROR", "priority must be one of 1,2,3,4")

    if due_string is not None and not isinstance(due_string, str):
        _record_run("failed", error_code="VALIDATION_ERROR", error_message="due_string must be a string")
        return _err("VALIDATION_ERROR", "due_string must be a string")

    due_date_norm, e = _parse_dt(due_date, "due_date")
    if e:
        _record_run("failed", error_code=e["error"]["code"], error_message=e["error"]["message"])
        return e

    deadline_norm, e = _parse_dt(deadline_at, "deadline_at")
    if e:
        _record_run("failed", error_code=e["error"]["code"], error_message=e["error"]["message"])
        return e

    if due_timezone is not None and not isinstance(due_timezone, str):
        _record_run("failed", error_code="VALIDATION_ERROR", error_message="due_timezone must be a string")
        return _err("VALIDATION_ERROR", "due_timezone must be a string")

    if project_id is not None and not _is_ulid_prefixed(project_id, "tdcnb"):
        _record_run("failed", error_code="VALIDATION_ERROR", error_message="project_id is invalid")
        return _err("VALIDATION_ERROR", "project_id is invalid")

    if section_id is not None and not _is_ulid_prefixed(section_id, "tdcnb"):
        _record_run("failed", error_code="VALIDATION_ERROR", error_message="section_id is invalid")
        return _err("VALIDATION_ERROR", "section_id is invalid")

    if parent_task_id is not None and not _is_ulid_prefixed(parent_task_id, "tdtsk"):
        _record_run("failed", error_code="VALIDATION_ERROR", error_message="parent_task_id is invalid")
        return _err("VALIDATION_ERROR", "parent_task_id is invalid")

    if label_ids is None:
        label_ids = []
    if not isinstance(label_ids, list) or any((not _is_ulid_prefixed(x, "tdlbl")) for x in label_ids):
        _record_run("failed", error_code="VALIDATION_ERROR", error_message="label_ids must be an array of tdlbl_... ids")
        return _err("VALIDATION_ERROR", "label_ids must be an array of tdlbl_... ids")

    # ---- Resolve connection (ambient auth) ----
    connections = _load("todoist_connections.json")
    conn = next((c for c in connections if c.get("id") == connection_id), None)
    if not conn:
        _record_run("failed", error_code="NOT_FOUND", error_message="connection not found")
        return _err("NOT_FOUND", "connection not found")
    if conn.get("status") != "active":
        # Ambient auth: search for any active connection that matches requested id? must be scoped by connection_id.
        _record_run("failed", error_code="UNAUTHORIZED", error_message="connection is not active")
        return _err("UNAUTHORIZED", "connection is not active")

    containers = _load("todoist_containers.json")
    tasks = _load("todoist_tasks.json")
    labels = _load("todoist_labels.json")

    # ---- Reference checks ----
    proj_row = None
    if project_id is not None:
        proj_row = next((r for r in containers if r.get("id") == project_id and r.get("connection_id") == connection_id), None)
        if not proj_row:
            _record_run("failed", error_code="NOT_FOUND", error_message="project_id not found")
            return _err("NOT_FOUND", "project_id not found")
        if proj_row.get("type") != "project" or proj_row.get("status") == "deleted":
            _record_run("failed", error_code="VALIDATION_ERROR", error_message="project_id must reference an active/archived project container")
            return _err("VALIDATION_ERROR", "project_id must reference an active/archived project container")

    sec_row = None
    if section_id is not None:
        sec_row = next((r for r in containers if r.get("id") == section_id and r.get("connection_id") == connection_id), None)
        if not sec_row:
            _record_run("failed", error_code="NOT_FOUND", error_message="section_id not found")
            return _err("NOT_FOUND", "section_id not found")
        if sec_row.get("type") != "section" or sec_row.get("status") == "deleted":
            _record_run("failed", error_code="VALIDATION_ERROR", error_message="section_id must reference an active/archived section container")
            return _err("VALIDATION_ERROR", "section_id must reference an active/archived section container")
        if project_id is None:
            _record_run("failed", error_code="VALIDATION_ERROR", error_message="section_id requires project_id")
            return _err("VALIDATION_ERROR", "section_id requires project_id")
        if sec_row.get("parent_project_id") != project_id:
            _record_run("failed", error_code="VALIDATION_ERROR", error_message="section_id does not belong to project_id")
            return _err("VALIDATION_ERROR", "section_id does not belong to project_id")

    parent_row = None
    if parent_task_id is not None:
        parent_row = next((t for t in tasks if t.get("id") == parent_task_id and t.get("connection_id") == connection_id), None)
        if not parent_row:
            _record_run("failed", error_code="NOT_FOUND", error_message="parent_task_id not found")
            return _err("NOT_FOUND", "parent_task_id not found")
        if parent_row.get("status") == "deleted":
            _record_run("failed", error_code="VALIDATION_ERROR", error_message="parent_task_id references a deleted task")
            return _err("VALIDATION_ERROR", "parent_task_id references a deleted task")

    # Labels must exist and belong to same connection; deleted labels not allowed to attach.
    lbl_map = {l.get("id"): l for l in labels if l.get("connection_id") == connection_id}
    for lid in label_ids:
        lr = lbl_map.get(lid)
        if not lr:
            _record_run("failed", error_code="NOT_FOUND", error_message=f"label_id not found: {lid}")
            return _err("NOT_FOUND", f"label_id not found: {lid}", label_id=lid)
        if lr.get("status") == "deleted":
            _record_run("failed", error_code="VALIDATION_ERROR", error_message=f"label_id is deleted: {lid}")
            return _err("VALIDATION_ERROR", f"label_id is deleted: {lid}", label_id=lid)

    # ---- Enforce container/name constraints where relevant ----
    # (task has no uniqueness constraints besides external_id which is null here)

    now = _now()
    task = {
        "id": _new_id("tdtsk"),
        "connection_id": connection_id,
        "external_id": None,
        "content": content.strip(),
        "description": description,
        "project_container_id": project_id,
        "section_container_id": section_id,
        "parent_task_id": parent_task_id,
        "priority": priority,
        "due_date": due_date_norm if due_date_norm is not None else None,
        "due_timezone": due_timezone if (due_date_norm is not None and due_timezone is not None) else (due_timezone if due_timezone is not None else None),
        "due_string_raw": (None if due_date_norm is not None else due_string),
        "deadline_at": deadline_norm,
        "label_ids": list(dict.fromkeys(label_ids)),
        "status": "active",
        "completed_at": None,
        "deleted_at": None,
        "created_at": now,
        "updated_at": now,
    }

    # Constraint: if section_container_id not null then project_container_id not null (already ensured via requiring project_id)
    # Constraint: parent_task_id same connection already checked.

    tasks.append(task)
    _save("todoist_tasks.json", tasks)

    _record_run("succeeded", connection_row=conn)
    return {"task": task}

def todoist_task_get(connection_id, task_id=None, query=None, project_id=None, section_id=None, parent_task_id=None, label_ids=None, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0360000" if __import__("os").path.isdir("./environment_mix/0360000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _is_ulid_prefixed(x, pref):
        if not isinstance(x, str):
            return False
        return re.match(r"^" + re.escape(pref) + r"_[0-9A-HJKMNP-TV-Z]{18,}$", x) is not None

    def _parse_cursor(cur):
        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur:
            return None, _err("VALIDATION_ERROR", "cursor must be a string")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("o:"):
                return None, _err("VALIDATION_ERROR", "cursor is invalid")
            off = int(s.split(":", 1)[1])
            if off < 0:
                return None, _err("VALIDATION_ERROR", "cursor is invalid")
            return off, None
        except (ValueError, UnicodeDecodeError, base64.binascii.Error):
            return None, _err("VALIDATION_ERROR", "cursor is invalid")

    def _make_cursor(off):
        s = f"o:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(s).decode("utf-8").rstrip("=")

    def _dt_key(v):
        if v is None:
            return None
        if isinstance(v, str):
            try:
                s = v
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.timestamp()
            except ValueError:
                return None
        return None

    def _sanitize_params():
        return {
            "connection_id": connection_id,
            "task_id": task_id,
            "query": query if isinstance(query, str) else None,
            "project_id": project_id,
            "section_id": section_id,
            "parent_task_id": parent_task_id,
            "label_ids": label_ids if isinstance(label_ids, list) else None,
            "status": status,
            "limit": limit,
            "cursor": cursor if isinstance(cursor, str) else None,
            "sort": sort,
            "order": order,
        }

    def _new_run_id():
        import secrets
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        b = ms.to_bytes(6, "big") + secrets.token_bytes(10)
        n = int.from_bytes(b, "big")
        out = []
        for _ in range(26):
            n, r = divmod(n, 32)
            out.append(alphabet[r])
        return "tdrun_" + "".join(reversed(out))

    def _record_run(status_run, http_status=None, error_code=None, error_message=None, connection_row=None):
        runs = _load("todoist_tool_runs.json")
        now = _now()
        dur = int((time.time() - start) * 1000)
        cid = connection_id if isinstance(connection_id, str) else (connection_row["id"] if connection_row else None)
        runs.append({
            "id": _new_run_id(),
            "connection_id": cid if cid else "unknown",
            "tool_name": "todoist_task_get",
            "request_params": _sanitize_params(),
            "status": status_run,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": dur,
            "assertions": None,
            "created_at": now,
            "updated_at": now,
        })
        _save("todoist_tool_runs.json", runs)

    # ---- Validation ----
    if not _is_ulid_prefixed(connection_id, "tdc"):
        _record_run("failed", error_code="VALIDATION_ERROR", error_message="connection_id is invalid")
        return _err("VALIDATION_ERROR", "connection_id is invalid")

    if task_id is not None and not _is_ulid_prefixed(task_id, "tdtsk"):
        _record_run("failed", error_code="VALIDATION_ERROR", error_message="task_id is invalid")
        return _err("VALIDATION_ERROR", "task_id is invalid")

    if project_id is not None and not _is_ulid_prefixed(project_id, "tdcnb"):
        _record_run("failed", error_code="VALIDATION_ERROR", error_message="project_id is invalid")
        return _err("VALIDATION_ERROR", "project_id is invalid")

    if section_id is not None and not _is_ulid_prefixed(section_id, "tdcnb"):
        _record_run("failed", error_code="VALIDATION_ERROR", error_message="section_id is invalid")
        return _err("VALIDATION_ERROR", "section_id is invalid")

    if parent_task_id is not None and not _is_ulid_prefixed(parent_task_id, "tdtsk"):
        _record_run("failed", error_code="VALIDATION_ERROR", error_message="parent_task_id is invalid")
        return _err("VALIDATION_ERROR", "parent_task_id is invalid")

    if query is not None and not isinstance(query, str):
        _record_run("failed", error_code="VALIDATION_ERROR", error_message="query must be a string")
        return _err("VALIDATION_ERROR", "query must be a string")

    if status is not None and status not in ("active", "completed", "deleted"):
        _record_run("failed", error_code="VALIDATION_ERROR", error_message="status must be one of active, completed, deleted")
        return _err("VALIDATION_ERROR", "status must be one of active, completed, deleted")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _record_run("failed", error_code="VALIDATION_ERROR", error_message="limit must be an integer between 1 and 200")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    if sort is None:
        sort = "updated_at"
    if sort not in ("created_at", "updated_at", "due_date", "priority", "order_index"):
        _record_run("failed", error_code="VALIDATION_ERROR", error_message="sort is invalid")
        return _err("VALIDATION_ERROR", "sort is invalid")

    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        _record_run("failed", error_code="VALIDATION_ERROR", error_message="order is invalid")
        return _err("VALIDATION_ERROR", "order is invalid")

    if label_ids is not None:
        if not isinstance(label_ids, list) or any((not _is_ulid_prefixed(x, "tdlbl")) for x in label_ids):
            _record_run("failed", error_code="VALIDATION_ERROR", error_message="label_ids must be an array of tdlbl_... ids")
            return _err("VALIDATION_ERROR", "label_ids must be an array of tdlbl_... ids")

    offset, e = _parse_cursor(cursor)
    if e:
        _record_run("failed", error_code=e["error"]["code"], error_message=e["error"]["message"])
        return e

    # ---- Resolve connection (ambient auth) ----
    connections = _load("todoist_connections.json")
    conn = next((c for c in connections if c.get("id") == connection_id), None)
    if not conn:
        _record_run("failed", error_code="NOT_FOUND", error_message="connection not found")
        return _err("NOT_FOUND", "connection not found")
    if conn.get("status") != "active":
        _record_run("failed", error_code="UNAUTHORIZED", error_message="connection is not active")
        return _err("UNAUTHORIZED", "connection is not active")

    tasks = _load("todoist_tasks.json")

    # Single fetch
    if task_id is not None:
        row = next((t for t in tasks if t.get("id") == task_id and t.get("connection_id") == connection_id), None)
        _record_run("succeeded", connection_row=conn)
        if not row:
            return {"tasks": [], "total": 0, "has_more": False, "next_cursor": None}
        return {"tasks": [row], "total": 1, "has_more": False, "next_cursor": None}

    # ---- Filter ----
    res = [t for t in tasks if t.get("connection_id") == connection_id]

    if query:
        q = query.casefold()
        res = [t for t in res if isinstance(t.get("content"), str) and q in t["content"].casefold()]

    if project_id is not None:
        res = [t for t in res if t.get("project_container_id") == project_id]
    if section_id is not None:
        res = [t for t in res if t.get("section_container_id") == section_id]
    if parent_task_id is not None:
        res = [t for t in res if t.get("parent_task_id") == parent_task_id]
    if status is not None:
        res = [t for t in res if t.get("status") == status]
    if label_ids is not None:
        want = set(label_ids)
        res = [t for t in res if want.issubset(set(t.get("label_ids") or []))]

    total = len(res)

    # ---- Sort ----
    reverse = (order == "desc")

    def sort_key(t):
        if sort in ("created_at", "updated_at"):
            return (_dt_key(t.get(sort)) or float("-inf"), t.get("id") or "")
        if sort == "due_date":
            # Put None last in asc, first in desc by using sentinel
            val = _dt_key(t.get("due_date"))
            if val is None:
                val = float("inf") if not reverse else float("-inf")
            return (val, _dt_key(t.get("updated_at")) or 0.0, t.get("id") or "")
        if sort == "priority":
            return (t.get("priority") or 0, _dt_key(t.get("updated_at")) or 0.0, t.get("id") or "")
        # order_index not present on tasks; keep deterministic fallback.
        return (_dt_key(t.get("updated_at")) or 0.0, t.get("id") or "")

    res.sort(key=sort_key, reverse=reverse)

    # ---- Page ----
    if offset is None:
        _record_run("failed", error_code="VALIDATION_ERROR", error_message="cursor is invalid")
        return _err("VALIDATION_ERROR", "cursor is invalid")

    page = res[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    _record_run("succeeded", connection_row=conn)
    return {"tasks": page, "total": total, "has_more": has_more, "next_cursor": next_cursor}

def todoist_task_update(connection_id, task_id=None, query=None, content=None, description=None, priority=None, due_string=None, due_date=None, due_timezone=None, deadline_at=None, label_ids=None, project_id=None, section_id=None, **_extra):
    import json, os, datetime, time, re, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0360000" if __import__("os").path.isdir("./environment_mix/0360000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        b = ms.to_bytes(6, "big") + secrets.token_bytes(10)
        v = int.from_bytes(b, "big")
        out = ""
        for _ in range(26):
            out = alphabet[v & 31] + out
            v >>= 5
        return f"{prefix}_{out}"

    def _parse_dt(v):
        if v is None:
            return None
        if not isinstance(v, str) or not v.strip():
            return "__invalid__"
        s = v.strip()
        try:
            if s.endswith("Z"):
                datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            else:
                datetime.datetime.fromisoformat(s)
            return s
        except Exception:
