                return _err("VALIDATION_ERROR", "content must be a non-empty string")
            if len(content) > 500:
                _log("failed", error_code="VALIDATION_ERROR", error_message="content length must be between 1 and 500", request_params=req_params)
                return _err("VALIDATION_ERROR", "content length must be between 1 and 500")

        if description is not None and not isinstance(description, str):
            _log("failed", error_code="VALIDATION_ERROR", error_message="description must be a string", request_params=req_params)
            return _err("VALIDATION_ERROR", "description must be a string")

        if priority is not None and priority not in (1, 2, 3, 4):
