            _log("failed", error_code="VALIDATION_ERROR", error_message="due_date must be an ISO 8601 date-time string", request_params=req_params)
            return _err("VALIDATION_ERROR", "due_date must be an ISO 8601 date-time string")

        dl = _parse_dt(deadline_at)
        if dl == "__invalid__":
            _log("failed", error_code="VALIDATION_ERROR", error_message="deadline_at must be an ISO 8601 date-time string", request_params=req_params)
