                    return _err("VALIDATION_ERROR", "label_ids contains malformed id")

        if project_id is not None:
            if not isinstance(project_id, str) or not project_id.startswith("tdcnb_"):
                _log("failed", error_code="VALIDATION_ERROR", error_message="project_id is malformed", request_params=req_params)
                return _err("VALIDATION_ERROR", "project_id is malformed")

        if section_id is not None:
            if not isinstance(section_id, str) or not section_id.startswith("tdcnb_"):
                _log("failed", error_code="VALIDATION_ERROR", error_message="section_id is malformed", request_params=req_params)
                return _err("VALIDATION_ERROR", "section_id is malformed")

        # connection context: must exist and not be disabled
        conns = _load("todoist_connections.json")
        conn = next((c for c in conns if c.get("id") == connection_id), None)
        if not conn or conn.get("status") == "disabled":
            _log("failed", error_code="UNAUTHORIZED", error_message="Connection not accessible", request_params=req_params)
            return _err("UNAUTHORIZED", "Connection not accessible")

        tasks = _load("todoist_tasks.json")
        containers = _load("todoist_containers.json")
        labels = _load("todoist_labels.json")

        # resolve target task
        target = None
        if task_id is not None:
            target = next((t for t in tasks if t.get("id") == task_id and t.get("connection_id") == connection_id), None)
            if not target:
                _log("failed", error_code="NOT_FOUND", error_message="task not found", request_params=req_params)
                return _err("NOT_FOUND", "task not found")
        else:
            q = query.strip().lower() if isinstance(query, str) else ""
            matches = [t for t in tasks if t.get("connection_id") == connection_id and t.get("status") != "deleted" and isinstance(t.get("content"), str) and q in t.get("content").lower()]
            matches.sort(key=lambda r: ((r.get("updated_at") or ""), r.get("id") or ""), reverse=True)
            if len(matches) == 0:
                _log("failed", error_code="VALIDATION_ERROR", error_message="query matched zero tasks; provide task_id", request_params=req_params)
                return _err("VALIDATION_ERROR", "query matched zero tasks; provide task_id")
            if len(matches) > 1:
                _log("failed", error_code="VALIDATION_ERROR", error_message="query matched multiple tasks; provide task_id", request_params=req_params)
                return _err("VALIDATION_ERROR", "query matched multiple tasks; provide task_id", matches_preview=[{"id": m.get("id"), "content": m.get("content")} for m in matches[:5]])
            target = matches[0]

        if target.get("status") == "deleted":
            _log("failed", error_code="INVALID_TRANSITION", error_message="Cannot update a deleted task", request_params=req_params)
            return _err("INVALID_TRANSITION", "Cannot update a deleted task")

        # validate container moves and relationship
        project_row = None
        section_row = None
        if project_id is not None:
            project_row = next((c for c in containers if c.get("id") == project_id and c.get("connection_id") == connection_id), None)
            if not project_row or project_row.get("type") != "project" or project_row.get("status") == "deleted":
                _log("failed", error_code="NOT_FOUND", error_message="project_id not found", request_params=req_params)
                return _err("NOT_FOUND", "project_id not found")
        if section_id is not None:
            section_row = next((c for c in containers if c.get("id") == section_id and c.get("connection_id") == connection_id), None)
            if not section_row or section_row.get("type") != "section" or section_row.get("status") == "deleted":
                _log("failed", error_code="NOT_FOUND", error_message="section_id not found", request_params=req_params)
                return _err("NOT_FOUND", "section_id not found")
            # must be compatible with project
            sec_parent = section_row.get("parent_project_id")
            if project_id is not None:
                if sec_parent != project_id:
                    _log("failed", error_code="VALIDATION_ERROR", error_message="section_id does not belong to project_id", request_params=req_params)
                    return _err("VALIDATION_ERROR", "section_id does not belong to project_id")
            else:
                # if only section_id provided, must keep/derive compatible project_id from section parent
                if not isinstance(sec_parent, str) or not sec_parent:
                    _log("failed", error_code="VALIDATION_ERROR", error_message="section_id missing parent project relationship", request_params=req_params)
                    return _err("VALIDATION_ERROR", "section_id missing parent project relationship")

        # validate parent_task cycles if a parent_task is being set via update? (tool doesn't include parent_task_id; ignore)

        # validate label_ids exist and are same connection and active (or allow deleted? rule says contains only existing label ids)
        if label_ids is not None:
            label_set = {l.get("id"): l for l in labels if l.get("connection_id") == connection_id}
            for lid in label_ids:
                if lid not in label_set or label_set[lid].get("status") == "deleted":
                    _log("failed", error_code="NOT_FOUND", error_message=f"label_id not found: {lid}", request_params=req_params)
                    return _err("NOT_FOUND", f"label_id not found: {lid}")

        # ensure at least one field is being updated
        any_update = any(v is not None for v in [content, description, priority, due_string, due_date, due_timezone, deadline_at, label_ids, project_id, section_id])
        if not any_update:
            _log("failed", error_code="VALIDATION_ERROR", error_message="No updatable fields provided", request_params=req_params)
            return _err("VALIDATION_ERROR", "No updatable fields provided")

        # apply updates
        if content is not None:
            target["content"] = content.strip()
        if description is not None:
            target["description"] = description
        if priority is not None:
            target["priority"] = priority
        if due_string is not None:
            target["due_string_raw"] = due_string
        if due_date is not None:
            target["due_date"] = dd
        if due_timezone is not None:
            target["due_timezone"] = due_timezone
        if deadline_at is not None:
            target["deadline_at"] = dl
        if label_ids is not None:
            target["label_ids"] = list(label_ids)

        # container move semantics
        if project_id is not None:
            target["project_container_id"] = project_id
            # if moving project without section specified, clear section
            if section_id is None:
                target["section_container_id"] = None
        if section_id is not None:
            target["section_container_id"] = section_id
            sec_parent = section_row.get("parent_project_id")
            # ensure project set
            target["project_container_id"] = project_id if project_id is not None else sec_parent

        target["updated_at"] = _now()

        # persist
        _save("todoist_tasks.json", tasks)
        _log("succeeded", request_params=req_params)

        return {"task": target}
    except Exception as e:
        _log("failed", error_code="failed", error_message=str(e), request_params=req_params)
        return _err("failed", str(e))

def todoist_task_delete(connection_id, task_id=None, query=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0360000" if __import__("os").path.isdir("./environment_mix/0360000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _is_ulid_prefixed(x, pref):
        if not isinstance(x, str):
            return False
        return re.match(r"^" + re.escape(pref) + r"_[0-9A-HJKMNP-TV-Z]{18,}$", x) is not None

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        b = ms.to_bytes(6, "big") + secrets.token_bytes(10)
        n = int.from_bytes(b, "big")
        out = []
        for _ in range(26):
            n, r = divmod(n, 32)
            out.append(alphabet[r])
        return f"{prefix}_" + "".join(reversed(out))

    def _sanitize_params():
        return {
            "connection_id": connection_id,
            "task_id": task_id,
            "query": query if isinstance(query, str) else None,
        }

    def _record_run(status_run, http_status=None, error_code=None, error_message=None, connection_row=None):
        runs = _load("todoist_tool_runs.json")
        now = _now()
        dur = int((time.time() - start) * 1000)
        cid = connection_id if isinstance(connection_id, str) else (connection_row["id"] if connection_row else None)
        runs.append({
            "id": _new_id("tdrun"),
            "connection_id": cid if cid else "unknown",
            "tool_name": "todoist_task_delete",
            "request_params": _sanitize_params(),
            "status": status_run,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": dur,
            "assertions": None,
            "created_at": now,
            "updated_at": now,
        })
        _save("todoist_tool_runs.json", runs)

    # ---- Validation ----
    if not _is_ulid_prefixed(connection_id, "tdc"):
        _record_run("failed", error_code="VALIDATION_ERROR", error_message="connection_id is invalid")
        return _err("VALIDATION_ERROR", "connection_id is invalid")

    if task_id is None and (query is None or (isinstance(query, str) and not query.strip())):
        _record_run("failed", error_code="VALIDATION_ERROR", error_message="either task_id or query is required")
        return _err("VALIDATION_ERROR", "either task_id or query is required")

    if task_id is not None and not _is_ulid_prefixed(task_id, "tdtsk"):
        _record_run("failed", error_code="VALIDATION_ERROR", error_message="task_id is invalid")
        return _err("VALIDATION_ERROR", "task_id is invalid")

    if query is not None and not isinstance(query, str):
        _record_run("failed", error_code="VALIDATION_ERROR", error_message="query must be a string")
        return _err("VALIDATION_ERROR", "query must be a string")

    # ---- Resolve connection ----
    connections = _load("todoist_connections.json")
    conn = next((c for c in connections if c.get("id") == connection_id), None)
    if not conn:
        _record_run("failed", error_code="NOT_FOUND", error_message="connection not found")
        return _err("NOT_FOUND", "connection not found")
    if conn.get("status") != "active":
        _record_run("failed", error_code="UNAUTHORIZED", error_message="connection is not active")
        return _err("UNAUTHORIZED", "connection is not active")

    tasks = _load("todoist_tasks.json")

    # ---- Find task ----
    target = None
    if task_id is not None:
        target = next((t for t in tasks if t.get("id") == task_id and t.get("connection_id") == connection_id), None)
        if not target:
            _record_run("failed", error_code="NOT_FOUND", error_message="task not found")
            return _err("NOT_FOUND", "task not found")
    else:
        q = query.strip().casefold()
        matches = [t for t in tasks if t.get("connection_id") == connection_id and isinstance(t.get("content"), str) and q in t["content"].casefold()]
        if len(matches) == 0:
            _record_run("failed", error_code="VALIDATION_ERROR", error_message="query matched zero tasks")
            return _err("VALIDATION_ERROR", "query matched zero tasks")
        def _dt_key(v):
            if not isinstance(v, str):
                return 0.0
            s = v
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.timestamp()
            except ValueError:
                return 0.0
        matches.sort(key=lambda t: (_dt_key(t.get("updated_at")), t.get("id") or ""), reverse=True)
        if len(matches) != 1:
            _record_run("failed", error_code="VALIDATION_ERROR", error_message="query matched multiple tasks; provide task_id")
            return _err("VALIDATION_ERROR", "query matched multiple tasks; provide task_id", matches_count=len(matches), top_task_ids=[m.get("id") for m in matches[:10]])
        target = matches[0]

    # ---- Delete transition (idempotent) ----
    if target.get("status") == "deleted":
        # idempotent: no mutation; but "no success without effect" for mutations is tricky.
        # Deleting already deleted is an accepted idempotent operation; treat as succeeded and return existing row.
        _record_run("succeeded", connection_row=conn)
        return {"task": target, "deleted": True, "idempotent": True}

    # Only legal transitions: active->deleted, completed->deleted
    if target.get("status") not in ("active", "completed"):
        _record_run("failed", error_code="INVALID_TRANSITION", error_message="task cannot be deleted from its current status")
        return _err("INVALID_TRANSITION", "task cannot be deleted from its current status")

    now = _now()
    target["status"] = "deleted"
    target["deleted_at"] = now
    # Ensure completed_at consistency: keep as-is; constraint only requires non-completed => completed_at null,
    # but deleted may have completed_at or not depending on history. We'll keep current.
    target["updated_at"] = now

    _save("todoist_tasks.json", tasks)
    _record_run("succeeded", connection_row=conn)
    return {"task": target, "deleted": True, "idempotent": False}

def todoist_task_complete(connection_id, task_id=None, query=None, **_extra):
    import json, os, datetime, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0360000" if __import__("os").path.isdir("./environment_mix/0360000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        b = ms.to_bytes(6, "big") + secrets.token_bytes(10)
        v = int.from_bytes(b, "big")
        out = ""
        for _ in range(26):
            out = alphabet[v & 31] + out
            v >>= 5
        return f"{prefix}_{out}"

    def _log(status, http_status=None, error_code=None, error_message=None, request_params=None):
        runs = _load("todoist_tool_runs.json")
        now = _now()
        dur = max(0, int((time.time() - t0) * 1000))
        runs.append({
            "id": _gen_id("tdrun"),
            "connection_id": connection_id if isinstance(connection_id, str) else "unknown",
            "tool_name": "todoist_task_complete",
            "request_params": request_params,
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": dur if status in ("succeeded", "failed") else None,
            "assertions": None,
            "created_at": now,
            "updated_at": now,
        })
        _save("todoist_tool_runs.json", runs)

    req_params = {"connection_id": connection_id, "task_id": task_id, "query": query}

    try:
        if not isinstance(connection_id, str) or not connection_id.strip() or not connection_id.startswith("tdc_"):
            _log("failed", error_code="VALIDATION_ERROR", error_message="connection_id is malformed", request_params=req_params)
            return _err("VALIDATION_ERROR", "connection_id is malformed")

        if task_id is None and (query is None or (isinstance(query, str) and not query.strip())):
            _log("failed", error_code="VALIDATION_ERROR", error_message="Either task_id or query must be provided", request_params=req_params)
            return _err("VALIDATION_ERROR", "Either task_id or query must be provided")

        if task_id is not None and (not isinstance(task_id, str) or not task_id.startswith("tdtsk_")):
            _log("failed", error_code="VALIDATION_ERROR", error_message="task_id is malformed", request_params=req_params)
            return _err("VALIDATION_ERROR", "task_id is malformed")
        if query is not None and not isinstance(query, str):
            _log("failed", error_code="VALIDATION_ERROR", error_message="query must be a string", request_params=req_params)
            return _err("VALIDATION_ERROR", "query must be a string")

        conns = _load("todoist_connections.json")
        conn = next((c for c in conns if c.get("id") == connection_id), None)
        if not conn or conn.get("status") == "disabled":
            _log("failed", error_code="UNAUTHORIZED", error_message="Connection not accessible", request_params=req_params)
            return _err("UNAUTHORIZED", "Connection not accessible")

        tasks = _load("todoist_tasks.json")

        target = None
        if task_id is not None:
            target = next((t for t in tasks if t.get("id") == task_id and t.get("connection_id") == connection_id), None)
            if not target:
                _log("failed", error_code="NOT_FOUND", error_message="task not found", request_params=req_params)
                return _err("NOT_FOUND", "task not found")
        else:
            q = query.strip().lower()
            matches = [t for t in tasks if t.get("connection_id") == connection_id and t.get("status") != "deleted" and isinstance(t.get("content"), str) and q in t.get("content").lower()]
            matches.sort(key=lambda r: ((r.get("updated_at") or ""), r.get("id") or ""), reverse=True)
            if len(matches) == 0:
                _log("failed", error_code="VALIDATION_ERROR", error_message="query matched zero tasks; provide task_id", request_params=req_params)
                return _err("VALIDATION_ERROR", "query matched zero tasks; provide task_id")
            if len(matches) > 1:
                _log("failed", error_code="VALIDATION_ERROR", error_message="query matched multiple tasks; provide task_id", request_params=req_params)
                return _err("VALIDATION_ERROR", "query matched multiple tasks; provide task_id", matches_preview=[{"id": m.get("id"), "content": m.get("content")} for m in matches[:5]])
            target = matches[0]

        # transitions: active -> completed; completed is idempotent; deleted cannot be completed
        if target.get("status") == "deleted":
            _log("failed", error_code="INVALID_TRANSITION", error_message="Cannot complete a deleted task", request_params=req_params)
            return _err("INVALID_TRANSITION", "Cannot complete a deleted task")

        if target.get("status") == "completed":
            # idempotent no-op
            if not target.get("completed_at"):
                target["completed_at"] = _now()
                target["updated_at"] = _now()
                _save("todoist_tasks.json", tasks)
            _log("succeeded", request_params=req_params)
            return {"task": target, "idempotent": True}

        if target.get("status") != "active":
            _log("failed", error_code="INVALID_TRANSITION", error_message=f"Cannot complete task from status '{target.get('status')}'", request_params=req_params)
            return _err("INVALID_TRANSITION", f"Cannot complete task from status '{target.get('status')}'")

        target["status"] = "completed"
        target["completed_at"] = _now()
        target["updated_at"] = _now()
        _save("todoist_tasks.json", tasks)

        _log("succeeded", request_params=req_params)
        return {"task": target}
    except Exception as e:
        _log("failed", error_code="failed", error_message=str(e), request_params=req_params)
