def todoist_tasks_bulk_create(connection_id, tasks, **_extra):
    import json, os, datetime, re, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0360000" if __import__("os").path.isdir("./environment_mix/0360000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_s = now.isoformat()

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(now.timestamp() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts & 31])
            ts >>= 5
        for _ in range(16):
            out.append(alphabet[random.getrandbits(5)])
        return prefix + "".join(reversed(out))

    def _log_run(conn_id, status, error_code=None, error_message=None, http_status=None, request_params=None, tool_name="todoist_tasks_bulk_create", duration_ms=None):
        runs = _load("todoist_tool_runs.json")
        rid = _new_id("tdrun_")
        row = {
            "id": rid,
            "connection_id": conn_id,
            "tool_name": tool_name,
            "request_params": request_params,
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": duration_ms,
            "assertions": None,
            "created_at": now_s,
            "updated_at": now_s,
        }
        runs.append(row)
        _save("todoist_tool_runs.json", runs)
        return row

    def _finish(run_row, status, error_code=None, error_message=None, http_status=None):
        runs = _load("todoist_tool_runs.json")
        for r in runs:
            if r.get("id") == run_row.get("id"):
                r["status"] = status
                r["error_code"] = error_code
                r["error_message"] = error_message
                r["http_status"] = http_status
                r["duration_ms"] = max(0, int((time.time() - t0) * 1000))
                r["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
                _save("todoist_tool_runs.json", runs)
                return r
        return run_row

    def _sanitize_params():
        # Avoid secrets; tasks contain no secrets, but keep size modest.
        prev = []
        if isinstance(tasks, list):
            for it in tasks[:20]:
                if isinstance(it, dict):
                    prev.append({k: it.get(k) for k in ["content", "project_id", "section_id", "parent_task_id", "priority", "due_string", "due_date", "deadline_at"] if k in it})
        return {"connection_id": connection_id, "tasks_preview": prev, "tasks_count": len(tasks) if isinstance(tasks, list) else None}

    # validate connection_id
    if not isinstance(connection_id, str) or not re.match(r"^tdc_[0-9A-HJKMNP-TV-Z]{18,}$", connection_id):
        run = _log_run(connection_id if isinstance(connection_id, str) else "unknown", "failed",
                       error_code="VALIDATION_ERROR", error_message="Invalid connection_id.", request_params=_sanitize_params())
        _finish(run, "failed", "VALIDATION_ERROR", "Invalid connection_id.")
        return _err("VALIDATION_ERROR", "Invalid connection_id.", field="connection_id")

    run = _log_run(connection_id, "running", request_params=_sanitize_params())

    conns = _load("todoist_connections.json")
    conn = next((c for c in conns if c.get("id") == connection_id), None)
    if not conn:
        _finish(run, "failed", "NOT_FOUND", "Connection not found.")
        return _err("NOT_FOUND", "Connection not found.", entity="todoist_connections", id=connection_id)
    if conn.get("status") != "active":
        _finish(run, "failed", "UNAUTHORIZED", "Connection is not active.")
        return _err("UNAUTHORIZED", "Connection is not active.", connection_status=conn.get("status"))

    if not isinstance(tasks, list) or len(tasks) < 1:
        _finish(run, "failed", "VALIDATION_ERROR", "tasks must be a non-empty array.")
        return _err("VALIDATION_ERROR", "tasks must be a non-empty array.", field="tasks")

    containers = _load("todoist_containers.json")
    labels = _load("todoist_labels.json")
    existing_tasks = _load("todoist_tasks.json")

    containers_by_id = {c.get("id"): c for c in containers if c.get("connection_id") == connection_id}
    tasks_by_id = {t.get("id"): t for t in existing_tasks if t.get("connection_id") == connection_id}
    labels_by_id = {l.get("id"): l for l in labels if l.get("connection_id") == connection_id and l.get("status") != "deleted"}

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string.", field=field)
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).isoformat(), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string.", field=field)

    def _check_cycle(new_task_id, parent_id):
        # new task not yet in tasks_by_id; cycle possible only if parent ancestry reaches new_task_id (won't).
        # Still, validate parent is not self (should never happen) and parent ancestry does not loop.
        seen = set()
        cur = parent_id
        while cur is not None:
            if cur == new_task_id:
                return False
            if cur in seen:
                return False
            seen.add(cur)
            pt = tasks_by_id.get(cur)
            if not pt:
                break
            cur = pt.get("parent_task_id")
        return True

    # Pre-validate all tasks; ensure atomicity (all-or-nothing)
    prepared = []
    for idx, it in enumerate(tasks):
        if not isinstance(it, dict):
            _finish(run, "failed", "VALIDATION_ERROR", f"tasks[{idx}] must be an object.")
            return _err("VALIDATION_ERROR", f"tasks[{idx}] must be an object.", index=idx)

        allowed = {"content","description","project_id","section_id","parent_task_id","priority","due_string","due_date","due_timezone","deadline_at","label_ids"}
        for k in it.keys():
            if k not in allowed:
                _finish(run, "failed", "VALIDATION_ERROR", f"tasks[{idx}] has unknown field '{k}'.")
                return _err("VALIDATION_ERROR", f"tasks[{idx}] has unknown field '{k}'.", index=idx, field=k)

        content = it.get("content")
        if not isinstance(content, str) or len(content.strip()) < 1 or len(content) > 500:
            _finish(run, "failed", "VALIDATION_ERROR", f"tasks[{idx}].content must be a non-empty string (1-500 chars).")
            return _err("VALIDATION_ERROR", f"tasks[{idx}].content must be a non-empty string (1-500 chars).", index=idx, field="content")

        desc = it.get("description")
        if desc is not None and not isinstance(desc, str):
            _finish(run, "failed", "VALIDATION_ERROR", f"tasks[{idx}].description must be a string.")
            return _err("VALIDATION_ERROR", f"tasks[{idx}].description must be a string.", index=idx, field="description")

        priority = it.get("priority", 1)
        if not isinstance(priority, int) or priority not in (1,2,3,4):
            _finish(run, "failed", "VALIDATION_ERROR", f"tasks[{idx}].priority must be one of 1,2,3,4.")
            return _err("VALIDATION_ERROR", f"tasks[{idx}].priority must be one of 1,2,3,4.", index=idx, field="priority")

        project_id = it.get("project_id")
        section_id = it.get("section_id")
        parent_task_id = it.get("parent_task_id")
        due_string = it.get("due_string")
        due_date = it.get("due_date")
        due_tz = it.get("due_timezone")
        deadline_at = it.get("deadline_at")
        label_ids = it.get("label_ids", [])

        if project_id is not None:
            if not isinstance(project_id, str) or not re.match(r"^tdcnb_[0-9A-HJKMNP-TV-Z]{18,}$", project_id):
                _finish(run, "failed", "VALIDATION_ERROR", f"tasks[{idx}].project_id is invalid.")
                return _err("VALIDATION_ERROR", f"tasks[{idx}].project_id is invalid.", index=idx, field="project_id")
            pc = containers_by_id.get(project_id)
            if not pc:
                _finish(run, "failed", "NOT_FOUND", f"tasks[{idx}].project_id not found.")
                return _err("NOT_FOUND", f"Project container not found for tasks[{idx}].project_id.", index=idx, field="project_id", id=project_id)
            if pc.get("type") != "project" or pc.get("status") == "deleted":
                _finish(run, "failed", "VALIDATION_ERROR", f"tasks[{idx}].project_id must reference an active project.")
                return _err("VALIDATION_ERROR", f"tasks[{idx}].project_id must reference an active project.", index=idx, field="project_id", id=project_id)

        if section_id is not None:
            if not isinstance(section_id, str) or not re.match(r"^tdcnb_[0-9A-HJKMNP-TV-Z]{18,}$", section_id):
                _finish(run, "failed", "VALIDATION_ERROR", f"tasks[{idx}].section_id is invalid.")
                return _err("VALIDATION_ERROR", f"tasks[{idx}].section_id is invalid.", index=idx, field="section_id")
            sc = containers_by_id.get(section_id)
            if not sc:
                _finish(run, "failed", "NOT_FOUND", f"tasks[{idx}].section_id not found.")
                return _err("NOT_FOUND", f"Section container not found for tasks[{idx}].section_id.", index=idx, field="section_id", id=section_id)
            if sc.get("type") != "section" or sc.get("status") == "deleted":
                _finish(run, "failed", "VALIDATION_ERROR", f"tasks[{idx}].section_id must reference an active section.")
                return _err("VALIDATION_ERROR", f"tasks[{idx}].section_id must reference an active section.", index=idx, field="section_id", id=section_id)
            # if section provided, require project provided and match parent_project_id
            if project_id is None:
                _finish(run, "failed", "VALIDATION_ERROR", f"tasks[{idx}] specifies section_id but no project_id.")
                return _err("VALIDATION_ERROR", f"tasks[{idx}] specifies section_id but no project_id.", index=idx, field="project_id")
            if sc.get("parent_project_id") != project_id:
                _finish(run, "failed", "VALIDATION_ERROR", f"tasks[{idx}].section_id does not belong to tasks[{idx}].project_id.")
                return _err("VALIDATION_ERROR", f"tasks[{idx}].section_id does not belong to tasks[{idx}].project_id.", index=idx, field="section_id",
                            section_id=section_id, expected_parent_project_id=sc.get("parent_project_id"), provided_project_id=project_id)

        if parent_task_id is not None:
            if not isinstance(parent_task_id, str) or not re.match(r"^tdtsk_[0-9A-HJKMNP-TV-Z]{18,}$", parent_task_id):
                _finish(run, "failed", "VALIDATION_ERROR", f"tasks[{idx}].parent_task_id is invalid.")
                return _err("VALIDATION_ERROR", f"tasks[{idx}].parent_task_id is invalid.", index=idx, field="parent_task_id")
            pt = tasks_by_id.get(parent_task_id)
            if not pt:
                _finish(run, "failed", "NOT_FOUND", f"tasks[{idx}].parent_task_id not found.")
                return _err("NOT_FOUND", f"Parent task not found for tasks[{idx}].parent_task_id.", index=idx, field="parent_task_id", id=parent_task_id)
            if pt.get("status") == "deleted":
                _finish(run, "failed", "VALIDATION_ERROR", f"tasks[{idx}].parent_task_id references a deleted task.")
                return _err("VALIDATION_ERROR", f"tasks[{idx}].parent_task_id references a deleted task.", index=idx, field="parent_task_id", id=parent_task_id)

        if due_string is not None and not isinstance(due_string, str):
            _finish(run, "failed", "VALIDATION_ERROR", f"tasks[{idx}].due_string must be a string.")
            return _err("VALIDATION_ERROR", f"tasks[{idx}].due_string must be a string.", index=idx, field="due_string")
        if due_tz is not None and not isinstance(due_tz, str):
            _finish(run, "failed", "VALIDATION_ERROR", f"tasks[{idx}].due_timezone must be a string.")
            return _err("VALIDATION_ERROR", f"tasks[{idx}].due_timezone must be a string.", index=idx, field="due_timezone")

        due_date_norm, err = _parse_dt(due_date, f"tasks[{idx}].due_date")
        if err:
            _finish(run, "failed", "VALIDATION_ERROR", err["error"]["message"])
            return err
        deadline_norm, err = _parse_dt(deadline_at, f"tasks[{idx}].deadline_at")
        if err:
            _finish(run, "failed", "VALIDATION_ERROR", err["error"]["message"])
            return err

        if label_ids is None:
            label_ids = []
        if not isinstance(label_ids, list):
            _finish(run, "failed", "VALIDATION_ERROR", f"tasks[{idx}].label_ids must be an array.")
            return _err("VALIDATION_ERROR", f"tasks[{idx}].label_ids must be an array.", index=idx, field="label_ids")
        normalized_label_ids = []
        for j, lid in enumerate(label_ids):
            if not isinstance(lid, str) or not re.match(r"^tdlbl_[0-9A-HJKMNP-TV-Z]{18,}$", lid):
                _finish(run, "failed", "VALIDATION_ERROR", f"tasks[{idx}].label_ids[{j}] is invalid.")
                return _err("VALIDATION_ERROR", f"tasks[{idx}].label_ids[{j}] is invalid.", index=idx, field="label_ids", label_index=j)
            if lid not in labels_by_id:
                _finish(run, "failed", "NOT_FOUND", f"tasks[{idx}].label_ids[{j}] not found.")
                return _err("NOT_FOUND", f"Label not found for tasks[{idx}].label_ids[{j}].", index=idx, field="label_ids", id=lid, label_index=j)
            normalized_label_ids.append(lid)

        new_id = _new_id("tdtsk_")
        if parent_task_id is not None and not _check_cycle(new_id, parent_task_id):
            _finish(run, "failed", "VALIDATION_ERROR", f"tasks[{idx}] would create a cycle in task hierarchy.")
            return _err("VALIDATION_ERROR", f"tasks[{idx}] would create a cycle in task hierarchy.", index=idx, field="parent_task_id")

        # due_date overrides due_string if both provided
        due_string_raw = due_string if (due_date_norm is None) else (due_string if due_string is not None else None)

        prepared.append({
            "id": new_id,
            "connection_id": connection_id,
            "external_id": None,
            "content": content,
            "description": desc,
            "project_container_id": project_id,
            "section_container_id": section_id,
            "parent_task_id": parent_task_id,
            "priority": priority,
            "due_date": due_date_norm,
            "due_timezone": due_tz,
            "due_string_raw": due_string_raw,
            "deadline_at": deadline_norm,
            "label_ids": normalized_label_ids,
            "status": "active",
            "completed_at": None,
            "deleted_at": None,
            "created_at": now_s,
            "updated_at": now_s,
        })

    # Commit atomically: append all
    existing_tasks.extend(prepared)
    _save("todoist_tasks.json", existing_tasks)
    _finish(run, "succeeded")
    return {"tasks": [dict(t) for t in prepared], "count": len(prepared)}

