            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string.", field=field)
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).isoformat(), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string.", field=field)

    due_date_norm = None
    if "due_date" in changes:
        due_date_norm, err = _parse_dt(changes.get("due_date"), "changes.due_date")
        if err:
            _finish(run, "failed", "VALIDATION_ERROR", err["error"]["message"])
            return err
    deadline_norm = None
    if "deadline_at" in changes:
        deadline_norm, err = _parse_dt(changes.get("deadline_at"), "changes.deadline_at")
        if err:
            _finish(run, "failed", "VALIDATION_ERROR", err["error"]["message"])
            return err

    containers = _load("todoist_containers.json")
    labels = _load("todoist_labels.json")
    all_tasks = _load("todoist_tasks.json")

    containers_by_id = {c.get("id"): c for c in containers if c.get("connection_id") == connection_id}
    labels_by_id = {l.get("id"): l for l in labels if l.get("connection_id") == connection_id and l.get("status") != "deleted"}
    tasks_by_id = {t.get("id"): t for t in all_tasks if t.get("connection_id") == connection_id}

    # validate move targets if provided
    move_project = changes.get("project_id") if "project_id" in changes else None
    move_section = changes.get("section_id") if "section_id" in changes else None
    if "project_id" in changes and move_project is not None:
        if not isinstance(move_project, str) or not re.match(r"^tdcnb_[0-9A-HJKMNP-TV-Z]{18,}$", move_project):
            _finish(run, "failed", "VALIDATION_ERROR", "changes.project_id is invalid.")
            return _err("VALIDATION_ERROR", "changes.project_id is invalid.", field="changes.project_id")
        pc = containers_by_id.get(move_project)
        if not pc:
            _finish(run, "failed", "NOT_FOUND", "changes.project_id not found.")
            return _err("NOT_FOUND", "Project container not found.", field="changes.project_id", id=move_project)
        if pc.get("type") != "project" or pc.get("status") == "deleted":
            _finish(run, "failed", "VALIDATION_ERROR", "changes.project_id must reference an active project.")
            return _err("VALIDATION_ERROR", "changes.project_id must reference an active project.", field="changes.project_id", id=move_project)

    if "section_id" in changes and move_section is not None:
        if not isinstance(move_section, str) or not re.match(r"^tdcnb_[0-9A-HJKMNP-TV-Z]{18,}$", move_section):
            _finish(run, "failed", "VALIDATION_ERROR", "changes.section_id is invalid.")
            return _err("VALIDATION_ERROR", "changes.section_id is invalid.", field="changes.section_id")
        sc = containers_by_id.get(move_section)
        if not sc:
            _finish(run, "failed", "NOT_FOUND", "changes.section_id not found.")
            return _err("NOT_FOUND", "Section container not found.", field="changes.section_id", id=move_section)
        if sc.get("type") != "section" or sc.get("status") == "deleted":
            _finish(run, "failed", "VALIDATION_ERROR", "changes.section_id must reference an active section.")
            return _err("VALIDATION_ERROR", "changes.section_id must reference an active section.", field="changes.section_id", id=move_section)
        # if moving into a section, require project_id change (or infer existing per-task) and must match
        if "project_id" in changes and move_project is not None:
            if sc.get("parent_project_id") != move_project:
                _finish(run, "failed", "VALIDATION_ERROR", "changes.section_id does not belong to changes.project_id.")
                return _err("VALIDATION_ERROR", "changes.section_id does not belong to changes.project_id.",
                            field="changes.section_id", section_id=move_section, provided_project_id=move_project, expected_parent_project_id=sc.get("parent_project_id"))

    # validate label replacement if provided
    new_label_ids = None
    if "label_ids" in changes:
        v = changes.get("label_ids")
        if v is None:
            v = []
        if not isinstance(v, list):
            _finish(run, "failed", "VALIDATION_ERROR", "changes.label_ids must be an array.")
            return _err("VALIDATION_ERROR", "changes.label_ids must be an array.", field="changes.label_ids")
        for i, lid in enumerate(v):
            if not isinstance(lid, str) or not re.match(r"^tdlbl_[0-9A-HJKMNP-TV-Z]{18,}$", lid):
                _finish(run, "failed", "VALIDATION_ERROR", "changes.label_ids contains an invalid id.")
                return _err("VALIDATION_ERROR", "changes.label_ids contains an invalid id.", field="changes.label_ids", index=i)
            if lid not in labels_by_id:
                _finish(run, "failed", "NOT_FOUND", "changes.label_ids references a label that does not exist (or is deleted).")
                return _err("NOT_FOUND", "Label not found.", field="changes.label_ids", id=lid, index=i)
        new_label_ids = list(v)

    # select matched tasks
    q = f_query.strip().lower() if isinstance(f_query, str) else None
    matched = []
    for t in all_tasks:
        if t.get("connection_id") != connection_id:
            continue
        if f_project is not None and t.get("project_container_id") != f_project:
            continue
        if f_section is not None and t.get("section_container_id") != f_section:
            continue
        if f_parent is not None and t.get("parent_task_id") != f_parent:
            continue
        if f_status is not None and t.get("status") != f_status:
            continue
        if f_label_ids is not None:
            tlabels = t.get("label_ids") or []
            if not all(lid in tlabels for lid in f_label_ids):
                continue
        if q is not None and q != "":
            if q not in ((t.get("content") or "").lower()):
                continue
        matched.append(t)

    if len(matched) == 0:
        _finish(run, "failed", "NOT_FOUND", "No tasks matched the provided filter.")
        return _err("NOT_FOUND", "No tasks matched the provided filter.", entity="todoist_tasks")

    # cannot update deleted tasks
    for t in matched:
        if t.get("status") == "deleted":
            _finish(run, "failed", "INVALID_TRANSITION", "Cannot update tasks with status='deleted'.")
            return _err("INVALID_TRANSITION", "Cannot update tasks with status='deleted'.", task_id=t.get("id"))

    # apply changes atomically
    # handle per-task validation for section/project relationship if moving section without explicit project
    for t in matched:
        if "section_id" in changes and move_section is not None:
            sc = containers_by_id.get(move_section)
            effective_project = move_project if ("project_id" in changes) else t.get("project_container_id")
            if effective_project is None:
                _finish(run, "failed", "VALIDATION_ERROR", "Cannot set section_id when task has no project and no project_id change provided.")
                return _err("VALIDATION_ERROR", "Cannot set section_id without a project_id.", task_id=t.get("id"))
            if sc and sc.get("parent_project_id") != effective_project:
                _finish(run, "failed", "VALIDATION_ERROR", "changes.section_id does not belong to the effective project for at least one matched task.")
                return _err("VALIDATION_ERROR", "changes.section_id does not belong to the effective project for at least one matched task.",
                            task_id=t.get("id"), section_id=move_section, effective_project_id=effective_project, expected_parent_project_id=sc.get("parent_project_id"))

    updated_ids = []
    for i, t in enumerate(all_tasks):
        if t.get("connection_id") != connection_id:
            continue
        if any(t.get("id") == m.get("id") for m in matched):
            if "content" in changes:
                t["content"] = changes.get("content")
            if "description" in changes:
                t["description"] = changes.get("description")
            if "priority" in changes:
                t["priority"] = changes.get("priority")
            if "due_date" in changes:
                t["due_date"] = due_date_norm
            if "due_string" in changes:
                # due_date overrides due_string for normalization, but we store raw string regardless for parity.
                t["due_string_raw"] = changes.get("due_string")
            if "due_timezone" in changes:
                t["due_timezone"] = changes.get("due_timezone")
            if "deadline_at" in changes:
                t["deadline_at"] = deadline_norm
            if "label_ids" in changes:
                t["label_ids"] = new_label_ids if new_label_ids is not None else []
            if "project_id" in changes:
                t["project_container_id"] = move_project
                # if project changes and section not explicitly set, keep section only if it still belongs; else clear
                if "section_id" not in changes:
                    sid = t.get("section_container_id")
                    if sid is not None:
                        sc = containers_by_id.get(sid)
                        if not sc or sc.get("parent_project_id") != move_project:
                            t["section_container_id"] = None
            if "section_id" in changes:
                t["section_container_id"] = move_section
                if move_section is not None and ("project_id" not in changes):
                    # ensure project is set to parent project if missing
                    sc = containers_by_id.get(move_section)
                    if sc and t.get("project_container_id") is None:
                        t["project_container_id"] = sc.get("parent_project_id")
            t["updated_at"] = now_s
            updated_ids.append(t.get("id"))

    if len(updated_ids) == 0:
        _finish(run, "failed", "NOT_FOUND", "No tasks were updated.")
        return _err("NOT_FOUND", "No tasks were updated.", entity="todoist_tasks")

    _save("todoist_tasks.json", all_tasks)
    _finish(run, "succeeded")
    return {"updated_task_ids": updated_ids, "updated_count": len(updated_ids)}

def todoist_tasks_bulk_delete(connection_id, filter, **_extra):
    import json, os, datetime, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0360000" if __import__("os").path.isdir("./environment_mix/0360000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        b = ms.to_bytes(6, "big") + secrets.token_bytes(10)
        v = int.from_bytes(b, "big")
        out = ""
        for _ in range(26):
            out = alphabet[v & 31] + out
            v >>= 5
        return f"{prefix}_{out}"

    def _log(status, http_status=None, error_code=None, error_message=None, request_params=None):
        runs = _load("todoist_tool_runs.json")
        now = _now()
        dur = max(0, int((time.time() - t0) * 1000))
        runs.append({
            "id": _gen_id("tdrun"),
            "connection_id": connection_id if isinstance(connection_id, str) else "unknown",
            "tool_name": "todoist_tasks_bulk_delete",
            "request_params": request_params,
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": dur if status in ("succeeded", "failed") else None,
            "assertions": None,
            "created_at": now,
            "updated_at": now,
        })
        _save("todoist_tool_runs.json", runs)

    req_params = {"connection_id": connection_id, "filter": filter}

    try:
        if not isinstance(connection_id, str) or not connection_id.strip() or not connection_id.startswith("tdc_"):
            _log("failed", error_code="VALIDATION_ERROR", error_message="connection_id is malformed", request_params=req_params)
            return _err("VALIDATION_ERROR", "connection_id is malformed")
        if not isinstance(filter, dict):
            _log("failed", error_code="VALIDATION_ERROR", error_message="filter must be an object", request_params=req_params)
            return _err("VALIDATION_ERROR", "filter must be an object")

        allowed = {"query", "project_id", "section_id", "parent_task_id", "label_ids", "status"}
        if any(k not in allowed for k in filter.keys()):
            _log("failed", error_code="VALIDATION_ERROR", error_message="filter contains unsupported fields", request_params=req_params)
            return _err("VALIDATION_ERROR", "filter contains unsupported fields")

        conns = _load("todoist_connections.json")
        conn = next((c for c in conns if c.get("id") == connection_id), None)
        if not conn or conn.get("status") == "disabled":
            _log("failed", error_code="UNAUTHORIZED", error_message="Connection not accessible", request_params=req_params)
            return _err("UNAUTHORIZED", "Connection not accessible")

        containers = _load("todoist_containers.json")
        labels = _load("todoist_labels.json")
        tasks = _load("todoist_tasks.json")

        q = filter.get("query")
        if q is not None and not isinstance(q, str):
            _log("failed", error_code="VALIDATION_ERROR", error_message="filter.query must be a string", request_params=req_params)
            return _err("VALIDATION_ERROR", "filter.query must be a string")

        project_id = filter.get("project_id")
        if project_id is not None and (not isinstance(project_id, str) or not project_id.startswith("tdcnb_")):
            _log("failed", error_code="VALIDATION_ERROR", error_message="filter.project_id is malformed", request_params=req_params)
            return _err("VALIDATION_ERROR", "filter.project_id is malformed")

        section_id = filter.get("section_id")
        if section_id is not None and (not isinstance(section_id, str) or not section_id.startswith("tdcnb_")):
            _log("failed", error_code="VALIDATION_ERROR", error_message="filter.section_id is malformed", request_params=req_params)
            return _err("VALIDATION_ERROR", "filter.section_id is malformed")

        parent_task_id = filter.get("parent_task_id")
        if parent_task_id is not None and (not isinstance(parent_task_id, str) or not parent_task_id.startswith("tdtsk_")):
            _log("failed", error_code="VALIDATION_ERROR", error_message="filter.parent_task_id is malformed", request_params=req_params)
            return _err("VALIDATION_ERROR", "filter.parent_task_id is malformed")

        label_ids = filter.get("label_ids")
        if label_ids is not None:
            if not isinstance(label_ids, list) or any(not isinstance(x, str) for x in label_ids):
                _log("failed", error_code="VALIDATION_ERROR", error_message="filter.label_ids must be an array of strings", request_params=req_params)
                return _err("VALIDATION_ERROR", "filter.label_ids must be an array of strings")
            for x in label_ids:
                if not x.startswith("tdlbl_"):
                    _log("failed", error_code="VALIDATION_ERROR", error_message="filter.label_ids contains malformed id", request_params=req_params)
                    return _err("VALIDATION_ERROR", "filter.label_ids contains malformed id")

        status = filter.get("status")
        if status is not None and status not in ("active", "completed", "deleted"):
            _log("failed", error_code="VALIDATION_ERROR", error_message="filter.status is invalid", request_params=req_params)
            return _err("VALIDATION_ERROR", "filter.status is invalid")

        # validate referenced containers exist for this connection (if provided)
        if project_id is not None:
            prow = next((c for c in containers if c.get("id") == project_id and c.get("connection_id") == connection_id and c.get("type") == "project" and c.get("status") != "deleted"), None)
            if not prow:
                _log("failed", error_code="NOT_FOUND", error_message="project_id not found", request_params=req_params)
                return _err("NOT_FOUND", "project_id not found")
        if section_id is not None:
            srow = next((c for c in containers if c.get("id") == section_id and c.get("connection_id") == connection_id and c.get("type") == "section" and c.get("status") != "deleted"), None)
            if not srow:
                _log("failed", error_code="NOT_FOUND", error_message="section_id not found", request_params=req_params)
                return _err("NOT_FOUND", "section_id not found")
            if project_id is not None and srow.get("parent_project_id") != project_id:
                _log("failed", error_code="VALIDATION_ERROR", error_message="section_id does not belong to project_id", request_params=req_params)
                return _err("VALIDATION_ERROR", "section_id does not belong to project_id")

        # for label_ids, require they exist (and not deleted) for this connection
        if label_ids is not None:
            label_map = {l.get("id"): l for l in labels if l.get("connection_id") == connection_id}
            for lid in label_ids:
                if lid not in label_map or label_map[lid].get("status") == "deleted":
                    _log("failed", error_code="NOT_FOUND", error_message=f"label_id not found: {lid}", request_params=req_params)
                    return _err("NOT_FOUND", f"label_id not found: {lid}")

        qlc = q.strip().lower() if isinstance(q, str) and q.strip() else None

        def _match_task(t):
            if t.get("connection_id") != connection_id:
                return False
            if status is not None and t.get("status") != status:
                return False
            if project_id is not None and t.get("project_container_id") != project_id:
                return False
            if section_id is not None and t.get("section_container_id") != section_id:
                return False
            if parent_task_id is not None and t.get("parent_task_id") != parent_task_id:
                return False
            if label_ids is not None:
                tids = t.get("label_ids") if isinstance(t.get("label_ids"), list) else []
                if not all(lid in tids for lid in label_ids):
                    return False
            if qlc is not None:
                content = t.get("content") or ""
                desc = t.get("description") or ""
                if qlc not in str(content).lower() and qlc not in str(desc).lower():
                    return False
            return True

        matches = [t for t in tasks if _match_task(t)]
        if not matches:
            _log("failed", error_code="NOT_FOUND", error_message="No tasks matched filter", request_params=req_params)
            return _err("NOT_FOUND", "No tasks matched filter")

        # apply transition to deleted; idempotent per-task, but overall must have effect
        now = _now()
        changed = 0
        for t in matches:
            if t.get("status") == "deleted":
                continue
            if t.get("status") in ("active", "completed"):
                t["status"] = "deleted"
                t["deleted_at"] = t.get("deleted_at") or now
                t["completed_at"] = None  # enforce constraint: non-completed must have completed_at null
                t["updated_at"] = now
                changed += 1

        if changed == 0:
            # all were already deleted -> report success but must not be "no effect" per contract; treat as conflict
            _log("failed", error_code="CONFLICT", error_message="All matched tasks are already deleted", request_params=req_params)
            return _err("CONFLICT", "All matched tasks are already deleted")

        _save("todoist_tasks.json", tasks)
        _log("succeeded", request_params=req_params)
        return {"deleted_count": changed, "matched_count": len(matches), "task_ids": [t.get("id") for t in matches]}
    except Exception as e:
        _log("failed", error_code="failed", error_message=str(e), request_params=req_params)
        return _err("failed", str(e))

