        if label_ids is not None:
            if not isinstance(label_ids, list) or any(not isinstance(x, str) for x in label_ids):
                _log("failed", error_code="VALIDATION_ERROR", error_message="filters.label_ids must be an array of strings", request_params=req_params)
                return _err("VALIDATION_ERROR", "filters.label_ids must be an array of strings")
            for x in label_ids:
                if not x.startswith("tdlbl_"):
                    _log("failed", error_code="VALIDATION_ERROR", error_message="filters.label_ids contains malformed id", request_params=req_params)
                    return _err("VALIDATION_ERROR", "filters.label_ids contains malformed id")
        if priority is not None and priority not in (1, 2, 3, 4):
            _log("failed", error_code="VALIDATION_ERROR", error_message="filters.priority is invalid", request_params=req_params)
            return _err("VALIDATION_ERROR", "filters.priority is invalid")
        if status is None:
            status = "active"
        if status is not None and status not in ("active", "completed", "deleted"):
            _log("failed", error_code="VALIDATION_ERROR", error_message="filters.status is invalid", request_params=req_params)
            return _err("VALIDATION_ERROR", "filters.status is invalid")
        if search is not None and not isinstance(search, str):
            _log("failed", error_code="VALIDATION_ERROR", error_message="filters.search must be a string", request_params=req_params)
            return _err("VALIDATION_ERROR", "filters.search must be a string")

        # validate referenced containers exist for this connection (if provided)
        if project_id is not None:
            prow = next((c for c in containers if c.get("id") == project_id and c.get("connection_id") == connection_id and c.get("type") == "project" and c.get("status") != "deleted"), None)
            if not prow:
                _log("failed", error_code="NOT_FOUND", error_message="project_id not found", request_params=req_params)
                return _err("NOT_FOUND", "project_id not found")
        if section_id is not None:
            srow = next((c for c in containers if c.get("id") == section_id and c.get("connection_id") == connection_id and c.get("type") == "section" and c.get("status") != "deleted"), None)
            if not srow:
                _log("failed", error_code="NOT_FOUND", error_message="section_id not found", request_params=req_params)
                return _err("NOT_FOUND", "section_id not found")
            if project_id is not None and srow.get("parent_project_id") != project_id:
                _log("failed", error_code="VALIDATION_ERROR", error_message="section_id does not belong to project_id", request_params=req_params)
                return _err("VALIDATION_ERROR", "section_id does not belong to project_id")

        # label existence
        if label_ids is not None:
            label_map = {l.get("id"): l for l in labels if l.get("connection_id") == connection_id}
            for lid in label_ids:
                if lid not in label_map or label_map[lid].get("status") == "deleted":
                    _log("failed", error_code="NOT_FOUND", error_message=f"label_id not found: {lid}", request_params=req_params)
                    return _err("NOT_FOUND", f"label_id not found: {lid}")

        slc = search.strip().lower() if isinstance(search, str) and search.strip() else None

        def _match_task(t):
            if t.get("connection_id") != connection_id:
                return False
            if status is not None and t.get("status") != status:
                return False
            if priority is not None and t.get("priority") != priority:
                return False
            if project_id is not None and t.get("project_container_id") != project_id:
                return False
            if section_id is not None and t.get("section_container_id") != section_id:
                return False
            if parent_task_id is not None and t.get("parent_task_id") != parent_task_id:
                return False
            if label_ids is not None:
                tids = t.get("label_ids") if isinstance(t.get("label_ids"), list) else []
                if not all(lid in tids for lid in label_ids):
                    return False
            if slc is not None:
                c = str(t.get("content") or "").lower()
                d = str(t.get("description") or "").lower()
                if slc not in c and slc not in d:
                    return False
            return True

        matches = [t for t in tasks if _match_task(t)]
        if not matches:
            _log("failed", error_code="NOT_FOUND", error_message="No tasks matched filters", request_params=req_params)
            return _err("NOT_FOUND", "No tasks matched filters")

        # deterministic ordering: updated_at desc, then id
        matches.sort(key=lambda r: ((r.get("updated_at") or ""), (r.get("id") or "")), reverse=True)
        selected = matches[:limit]

        if dry_run:
            _log("succeeded", request_params=req_params)
            return {"dry_run": True, "matched_count": len(matches), "selected_count": len(selected), "tasks": selected}

        now = _now()
        changed = 0
        for t in selected:
            if t.get("status") == "active":
                t["status"] = "completed"
                t["completed_at"] = t.get("completed_at") or now
                t["updated_at"] = now
                changed += 1
            elif t.get("status") == "completed":
                # idempotent; do not clear completed_at
                if not t.get("completed_at"):
                    t["completed_at"] = now
                    t["updated_at"] = now
                    changed += 1
            # deleted: no transition
        if changed == 0:
            _log("failed", error_code="CONFLICT", error_message="Selected tasks could not be completed (already completed/deleted)", request_params=req_params)
            return _err("CONFLICT", "Selected tasks could not be completed (already completed/deleted)")

        _save("todoist_tasks.json", tasks)
        _log("succeeded", request_params=req_params)
        return {"completed_count": changed, "matched_count": len(matches), "selected_count": len(selected), "task_ids": [t.get("id") for t in selected]}
    except Exception as e:
        _log("failed", error_code="failed", error_message=str(e), request_params=req_params)
        return _err("failed", str(e))

def todoist_project_get(connection_id, status=None, limit=None, cursor=None, sort=None, sort_dir=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0360000" if __import__("os").path.isdir("./environment_mix/0360000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _match(pat, s):
        return isinstance(s, str) and re.match(pat, s) is not None

    def _cursor_decode(c):
        try:
            pad = "=" * (-len(c) % 4)
            v = base64.urlsafe_b64decode((c + pad).encode("ascii")).decode("utf-8")
            i = int(v)
            return i
        except Exception:
            return None

    def _cursor_encode(i):
        return base64.urlsafe_b64encode(str(i).encode("utf-8")).decode("ascii").rstrip("=")

    def _record_run(conn_id, tool_name, request_params, status_s, duration_ms=None, http_status=None, error_code=None, error_message=None):
        runs = _load("todoist_tool_runs.json")
        now = _now_iso()
        run_id = "tdrun_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        row = {
            "id": run_id,
            "connection_id": conn_id,
            "tool_name": tool_name,
            "request_params": request_params,
            "status": "running",
            "http_status": None,
            "error_code": None,
            "error_message": None,
            "duration_ms": None,
            "assertions": None,
            "created_at": now,
            "updated_at": now,
        }
        runs.append(row)
        _save("todoist_tool_runs.json", runs)

        for r in runs[::-1]:
            if r.get("id") == run_id:
                r["status"] = status_s
                r["http_status"] = http_status
                r["error_code"] = error_code
                r["error_message"] = error_message
                r["duration_ms"] = duration_ms
                r["updated_at"] = _now_iso()
                break
        _save("todoist_tool_runs.json", runs)

    # Validate
    if not _match(r"^tdc_[0-9A-HJKMNP-TV-Z]{16,}$", connection_id):
        return _err("VALIDATION_ERROR", "connection_id is malformed")
    if status is not None and status not in ("active", "archived", "deleted"):
        return _err("VALIDATION_ERROR", "status must be one of active, archived, deleted")
    if limit is not None:
        if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 500:
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if sort is not None and sort not in ("order_index", "name", "created_at", "updated_at"):
        return _err("VALIDATION_ERROR", "sort must be one of order_index, name, created_at, updated_at")
    if sort_dir is not None and sort_dir not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sort_dir must be one of asc, desc")

    # Auth: connection exists and not disabled
    conns = _load("todoist_connections.json")
    conn = next((c for c in conns if c.get("id") == connection_id and c.get("status") in ("active", "invalid_token")), None)
    if not conn:
        exists = next((c for c in conns if c.get("id") == connection_id), None)
        duration_ms = int((time.time() - t0) * 1000)
        if exists and exists.get("status") == "disabled":
            _record_run(connection_id, "todoist_project_get", {"connection_id": connection_id, "status": status, "limit": limit, "cursor": cursor, "sort": sort, "sort_dir": sort_dir},
                        "failed", duration_ms, None, "UNAUTHORIZED", "Connection is disabled")
            return _err("UNAUTHORIZED", "Connection is not accessible")
        _record_run(connection_id, "todoist_project_get", {"connection_id": connection_id, "status": status, "limit": limit, "cursor": cursor, "sort": sort, "sort_dir": sort_dir},
                    "failed", duration_ms, None, "UNAUTHORIZED", "No accessible connection found")
        return _err("UNAUTHORIZED", "No accessible connection found")

    containers = _load("todoist_containers.json")
    rows = [c for c in containers if c.get("connection_id") == connection_id and c.get("type") == "project"]

    # Default exclude deleted
    if status is None:
        rows = [r for r in rows if r.get("status") != "deleted"]
    else:
        rows = [r for r in rows if r.get("status") == status]

    sfield = sort or "order_index"
    sdir = sort_dir or "asc"

    def _safe_int(v):
        return v if isinstance(v, int) and not isinstance(v, bool) else None

    def _k(r):
        if sfield == "order_index":
            oi = _safe_int(r.get("order_index"))
            return (oi if oi is not None else 10**18, (r.get("name") or "").lower(), r.get("id") or "")
        if sfield == "name":
            return ((r.get("name") or "").lower(), r.get("id") or "")
        if sfield == "created_at":
            return (r.get("created_at") or "", r.get("id") or "")
        return (r.get("updated_at") or "", r.get("id") or "")

    rows.sort(key=_k, reverse=(sdir == "desc"))

    start = 0
    if cursor:
        start_i = _cursor_decode(cursor)
        if start_i is None or start_i < 0:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        start = start_i

    lim = limit if limit is not None else 500
    page = rows[start:start + lim]
    next_cursor = _cursor_encode(start + lim) if start + lim < len(rows) else None

    # Sanitize: never return api_token_ciphertext (not in this collection anyway)
    duration_ms = int((time.time() - t0) * 1000)
    _record_run(connection_id, "todoist_project_get",
                {"connection_id": connection_id, "status": status, "limit": limit, "cursor": cursor, "sort": sort, "sort_dir": sort_dir},
                "succeeded", duration_ms, None, None, None)

    return {
        "connection_id": connection_id,
        "projects": page,
        "total": len(rows),
        "limit": lim,
        "cursor": cursor,
        "has_more": next_cursor is not None,
        "next_cursor": next_cursor,
        "sort": sfield,
        "sort_dir": sdir,
    }

def todoist_section_get(connection_id, project_id, status=None, limit=None, cursor=None, sort=None, sort_dir=None, **_extra):
    import json, os, datetime, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0360000" if __import__("os").path.isdir("./environment_mix/0360000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                d = json.load(f)
                return d if isinstance(d, list) else []
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        b = ms.to_bytes(6, "big") + secrets.token_bytes(10)
        v = int.from_bytes(b, "big")
        out = ""
        for _ in range(26):
            out = alphabet[v & 31] + out
            v >>= 5
        return f"{prefix}_{out}"

    def _log(status_run, http_status=None, error_code=None, error_message=None, request_params=None):
        runs = _load("todoist_tool_runs.json")
        now = _now()
        dur = max(0, int((time.time() - t0) * 1000))
        runs.append({
            "id": _gen_id("tdrun"),
            "connection_id": connection_id if isinstance(connection_id, str) else "unknown",
            "tool_name": "todoist_section_get",
            "request_params": request_params,
            "status": status_run,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": dur if status_run in ("succeeded", "failed") else None,
            "assertions": None,
            "created_at": now,
            "updated_at": now,
        })
        _save("todoist_tool_runs.json", runs)

    req_params = {"connection_id": connection_id, "project_id": project_id, "status": status, "limit": limit, "cursor": cursor, "sort": sort, "sort_dir": sort_dir}

    try:
        if not isinstance(connection_id, str) or not connection_id.strip():
            _log("failed", error_code="VALIDATION_ERROR", error_message="connection_id is required", request_params=req_params)
            return _err("VALIDATION_ERROR", "connection_id is required")
        # Relax: do not reject "inbox" style project_id; treat as "no sections".
        if not isinstance(project_id, str) or not project_id.strip():
            _log("failed", error_code="VALIDATION_ERROR", error_message="project_id is required", request_params=req_params)
            return _err("VALIDATION_ERROR", "project_id is required")

        if status is not None and status not in ("active", "archived", "deleted"):
            _log("failed", error_code="VALIDATION_ERROR", error_message="status must be one of active, archived, deleted", request_params=req_params)
            return _err("VALIDATION_ERROR", "status must be one of active, archived, deleted")
        if sort is not None and sort not in ("order_index", "name", "created_at", "updated_at"):
            _log("failed", error_code="VALIDATION_ERROR", error_message="sort is invalid", request_params=req_params)
            return _err("VALIDATION_ERROR", "sort is invalid")
        if sort_dir is not None and sort_dir not in ("asc", "desc"):
            _log("failed", error_code="VALIDATION_ERROR", error_message="sort_dir is invalid", request_params=req_params)
            return _err("VALIDATION_ERROR", "sort_dir is invalid")

        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 500:
            _log("failed", error_code="VALIDATION_ERROR", error_message="limit must be between 1 and 500", request_params=req_params)
            return _err("VALIDATION_ERROR", "limit must be between 1 and 500")

        conns = _load("todoist_connections.json")
        conn = next((c for c in conns if c.get("id") == connection_id), None)
        if not conn or conn.get("status") == "disabled":
            _log("failed", error_code="UNAUTHORIZED", error_message="no accessible connection found for connection_id", request_params=req_params)
            return _err("UNAUTHORIZED", "no accessible connection found for connection_id")

        containers = _load("todoist_containers.json")

        # Determine if project_id maps to an actual project container. If not (e.g., "inbox"), return empty.
        project_row = next((c for c in containers if c.get("connection_id") == connection_id and c.get("id") == project_id and c.get("type") == "project" and c.get("status") != "deleted"), None)
        if not project_row:
            # normal empty data
            _log("succeeded", request_params=req_params)
            return {"sections": [], "total": 0, "has_more": False, "next_cursor": None}

        rows = [c for c in containers if c.get("connection_id") == connection_id and c.get("type") == "section" and c.get("parent_project_id") == project_id]
        if status is not None:
            rows = [r for r in rows if r.get("status") == status]
        else:
            # default: exclude deleted (consistent with "get" behaviors)
            rows = [r for r in rows if r.get("status") != "deleted"]

        sort_field = sort or "order_index"
        direction = sort_dir or "asc"

        def _sf(v):
            if v is None:
                return ""
            return v

        def _key(r):
            if sort_field == "order_index":
                oi = r.get("order_index")
                oi = oi if isinstance(oi, int) else 10**18
                return (oi, (r.get("id") or ""))
            if sort_field == "name":
                return ((r.get("name") or "").lower(), (r.get("id") or ""))
            return (_sf(r.get(sort_field) or ""), (r.get("id") or ""))

        rows.sort(key=_key, reverse=(direction == "desc"))

        start = 0
        if cursor is not None:
            # cursor is last seen id
            if isinstance(cursor, str) and cursor:
                for i, r in enumerate(rows):
                    if r.get("id") == cursor:
                        start = i + 1
                        break

        page = rows[start:start + limit]
        next_cursor = page[-1].get("id") if len(page) == limit else None
        has_more = (start + limit) < len(rows)

        _log("succeeded", request_params=req_params)
        return {"sections": page, "total": len(rows), "has_more": bool(has_more), "next_cursor": next_cursor}
    except Exception as e:
        _log("failed", error_code="failed", error_message=str(e), request_params=req_params)
        return _err("failed", "unexpected error", detail=str(e))

def todoist_project_create(connection_id, name, parent_project_id=None, color=None, order_index=None, is_favorite=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0360000" if __import__("os").path.isdir("./environment_mix/0360000") else "/app/database")
