        # We'll generate a sortable string and rely on pattern checks at input only.
        return prefix + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")

    def _record_run(conn_id, tool_name, request_params, status_s, duration_ms=None, http_status=None, error_code=None, error_message=None):
