            "error_message": None,
            "duration_ms": None,
            "assertions": None,
            "created_at": now,
            "updated_at": now,
        }
        runs.append(row)
        _save("todoist_tool_runs.json", runs)

        for r in runs[::-1]:
            if r.get("id") == run_id:
                r["status"] = status_s
                r["http_status"] = http_status
                r["error_code"] = error_code
                r["error_message"] = error_message
                r["duration_ms"] = duration_ms
                r["updated_at"] = _now_iso()
                break
        _save("todoist_tool_runs.json", runs)

    # Validate
    if not _match(r"^tdc_[0-9A-HJKMNP-TV-Z]{16,}$", connection_id):
        return _err("VALIDATION_ERROR", "connection_id is malformed")
    if not isinstance(name, str) or len(name.strip()) < 1:
        return _err("VALIDATION_ERROR", "name is required and must be a non-empty string")
    if parent_project_id is not None and not _match(r"^tdcnb_[0-9A-HJKMNP-TV-Z]{16,}$", parent_project_id):
        return _err("VALIDATION_ERROR", "parent_project_id is malformed")
    if color is not None and not isinstance(color, str):
        return _err("VALIDATION_ERROR", "color must be a string")
    if order_index is not None:
        if not isinstance(order_index, int) or isinstance(order_index, bool) or order_index < 0:
            return _err("VALIDATION_ERROR", "order_index must be an integer >= 0")
    if is_favorite is not None and not isinstance(is_favorite, bool):
        return _err("VALIDATION_ERROR", "is_favorite must be a boolean")

    # Auth: connection exists and not disabled
    conns = _load("todoist_connections.json")
