                        "failed", duration_ms, None, "UNAUTHORIZED", "Connection is disabled")
            return _err("UNAUTHORIZED", "Connection is not accessible")
        _record_run(connection_id, "todoist_project_create", {"connection_id": connection_id, "name": name, "parent_project_id": parent_project_id, "color": color, "order_index": order_index, "is_favorite": is_favorite},
                    "failed", duration_ms, None, "UNAUTHORIZED", "No accessible connection found")
        return _err("UNAUTHORIZED", "No accessible connection found")

    containers = _load("todoist_containers.json")

    # Parent project validation (must exist, same connection, type=project, not deleted)
    if parent_project_id is not None:
        parent = next((c for c in containers if c.get("id") == parent_project_id), None)
        if not parent or parent.get("connection_id") != connection_id or parent.get("type") != "project" or parent.get("status") == "deleted":
            duration_ms = int((time.time() - t0) * 1000)
