                        "failed", duration_ms, None, "NOT_FOUND", "parent_project_id not found")
            return _err("NOT_FOUND", "parent_project_id not found")

    # Uniqueness: unique(connection_id, type, lower(name)) for projects
    lname = name.strip().lower()
    for c in containers:
