        now = _now()
        dur = max(0, int((time.time() - t0) * 1000))
        runs.append({
            "id": _gen_id("tdrun"),
            "connection_id": connection_id if isinstance(connection_id, str) else "unknown",
            "tool_name": "todoist_comment_get",
            "request_params": request_params,
            "status": status_run,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": dur if status_run in ("succeeded", "failed") else None,
            "assertions": None,
            "created_at": now,
            "updated_at": now,
        })
        _save("todoist_tool_runs.json", runs)

    req_params = {"connection_id": connection_id, "task_id": task_id, "project_id": project_id, "status": status, "limit": limit, "cursor": cursor, "sort": sort, "sort_dir": sort_dir}

    try:
        if not isinstance(connection_id, str) or not connection_id.strip():
            _log("failed", error_code="VALIDATION_ERROR", error_message="connection_id is required", request_params=req_params)
            return _err("VALIDATION_ERROR", "connection_id is required")

        conns = _load("todoist_connections.json")
        conn = next((c for c in conns if c.get("id") == connection_id), None)
        if not conn or conn.get("status") == "disabled":
            _log("failed", error_code="UNAUTHORIZED", error_message="no accessible connection found for connection_id", request_params=req_params)
            return _err("UNAUTHORIZED", "no accessible connection found for connection_id")

        # Relax: some clients may send both task_id and project_id; prefer task_id (do not error).
        if task_id is None and project_id is None:
            _log("failed", error_code="VALIDATION_ERROR", error_message="either task_id or project_id is required", request_params=req_params)
            return _err("VALIDATION_ERROR", "either task_id or project_id is required")

        if task_id is not None and (not isinstance(task_id, str) or not task_id.startswith("tdtsk_")):
            _log("failed", error_code="VALIDATION_ERROR", error_message="task_id is malformed", request_params=req_params)
            return _err("VALIDATION_ERROR", "task_id is malformed")
        if project_id is not None and (not isinstance(project_id, str) or not project_id.startswith("tdcnb_")):
            # allow "inbox" here? For comments, "inbox" isn't a container id. Treat as empty result.
            if isinstance(project_id, str) and project_id == "inbox":
                _log("succeeded", request_params=req_params)
                return {"comments": [], "total": 0, "has_more": False, "next_cursor": None}
            _log("failed", error_code="VALIDATION_ERROR", error_message="project_id is malformed", request_params=req_params)
            return _err("VALIDATION_ERROR", "project_id is malformed")

        if status is not None and status not in ("active", "deleted"):
            _log("failed", error_code="VALIDATION_ERROR", error_message="status must be one of active, deleted", request_params=req_params)
            return _err("VALIDATION_ERROR", "status must be one of active, deleted")
        if sort is not None and sort not in ("posted_at", "created_at", "updated_at"):
            _log("failed", error_code="VALIDATION_ERROR", error_message="sort is invalid", request_params=req_params)
            return _err("VALIDATION_ERROR", "sort is invalid")
        if sort_dir is not None and sort_dir not in ("asc", "desc"):
            _log("failed", error_code="VALIDATION_ERROR", error_message="sort_dir is invalid", request_params=req_params)
            return _err("VALIDATION_ERROR", "sort_dir is invalid")
        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 500:
            _log("failed", error_code="VALIDATION_ERROR", error_message="limit must be between 1 and 500", request_params=req_params)
            return _err("VALIDATION_ERROR", "limit must be between 1 and 500")

        comments = _load("todoist_comments.json")

        use_task = task_id is not None
        rows = [c for c in comments if c.get("connection_id") == connection_id and ((c.get("task_id") == task_id) if use_task else (c.get("project_container_id") == project_id))]

        if status is not None:
            rows = [r for r in rows if r.get("status") == status]
        else:
            rows = [r for r in rows if r.get("status") != "deleted"]

        sort_field = sort or "posted_at"
        direction = sort_dir or "desc"

        def _sf(v):
            if v is None:
                return ""
            return v

        def _key(r):
            # posted_at can be null; fall back to created_at for stable ordering.
            if sort_field == "posted_at":
                return (_sf(r.get("posted_at") or r.get("created_at") or ""), (r.get("id") or ""))
            return (_sf(r.get(sort_field) or ""), (r.get("id") or ""))

        rows.sort(key=_key, reverse=(direction == "desc"))

        start = 0
        if cursor is not None and isinstance(cursor, str) and cursor:
            for i, r in enumerate(rows):
                if r.get("id") == cursor:
                    start = i + 1
                    break

        page = rows[start:start + limit]
        next_cursor = page[-1].get("id") if len(page) == limit else None
        has_more = (start + limit) < len(rows)

        _log("succeeded", request_params=req_params)
        return {"comments": page, "total": len(rows), "has_more": bool(has_more), "next_cursor": next_cursor}
    except Exception as e:
        _log("failed", error_code="failed", error_message=str(e), request_params=req_params)
        return _err("failed", "unexpected error", detail=str(e))

def todoist_label_get(connection_id, status=None, limit=None, cursor=None, sort=None, sort_dir=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0360000" if __import__("os").path.isdir("./environment_mix/0360000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        b = ts.to_bytes(6, "big") + os.urandom(10)
        out = ""
        v = int.from_bytes(b, "big")
        for _ in range(26):
            out = alphabet[v & 31] + out
            v >>= 5
        return f"{prefix}_{out}"

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            if s.endswith("Z"):
                s2 = s[:-1]
                try:
                    datetime.datetime.fromisoformat(s2)
                    return s2 + "Z"
                except ValueError:
                    return None
            try:
                datetime.datetime.fromisoformat(s)
                return s
            except ValueError:
                return None
        return None

    def _dt_key(v):
        p = _parse_dt(v)
        if not p:
            return datetime.datetime(1970, 1, 1)
        s = p[:-1] if p.endswith("Z") else p
        try:
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return datetime.datetime(1970, 1, 1)

    def _encode_cursor(obj):
        raw = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur.strip():
            return None
        s = cur.strip()
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _log_run(connection_id_val, params_sanitized, status_val, error_code=None, error_message=None, http_status=None, assertions=None):
