    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        b = ms.to_bytes(6, "big") + secrets.token_bytes(10)
        v = int.from_bytes(b, "big")
        out = ""
        for _ in range(26):
            out = alphabet[v & 31] + out
            v >>= 5
        return f"{prefix}_{out}"

    def _log(status_run, http_status=None, error_code=None, error_message=None, request_params=None):
        runs = _load("todoist_tool_runs.json")
        now = _now()
        dur = max(0, int((time.time() - t0) * 1000))
        runs.append({
            "id": _gen_id("tdrun"),
            "connection_id": connection_id if isinstance(connection_id, str) else "unknown",
            "tool_name": "todoist_label_delete",
            "request_params": request_params,
            "status": status_run,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": dur if status_run in ("succeeded", "failed") else None,
            "assertions": None,
            "created_at": now,
            "updated_at": now,
        })
        _save("todoist_tool_runs.json", runs)

    req_params = {"connection_id": connection_id, "label_id": label_id}

    try:
        # Relax schema regex (store has tdc_01J..., not only 01H...)
        if not isinstance(connection_id, str) or not connection_id.strip() or not connection_id.startswith("tdc_"):
            _log("failed", error_code="VALIDATION_ERROR", error_message="connection_id is malformed", request_params=req_params)
            return _err("VALIDATION_ERROR", "connection_id is malformed")
        if not isinstance(label_id, str) or not label_id.startswith("tdlbl_"):
            _log("failed", error_code="VALIDATION_ERROR", error_message="label_id is malformed", request_params=req_params)
            return _err("VALIDATION_ERROR", "label_id is malformed")

        conns = _load("todoist_connections.json")
        conn = next((c for c in conns if c.get("id") == connection_id), None)
        if not conn or conn.get("status") == "disabled":
            _log("failed", error_code="UNAUTHORIZED", error_message="Connection not accessible", request_params=req_params)
            return _err("UNAUTHORIZED", "Connection not accessible")

        labels = _load("todoist_labels.json")
        tasks = _load("todoist_tasks.json")

        label = next((l for l in labels if l.get("id") == label_id and l.get("connection_id") == connection_id), None)
        if not label:
            _log("failed", error_code="NOT_FOUND", error_message="label not found", request_params=req_params)
            return _err("NOT_FOUND", "label not found")

        if label.get("status") == "deleted":
            # idempotent delete is not specified; spec says may raise CONFLICT if already deleted
            _log("failed", error_code="CONFLICT", error_message="label is already deleted", request_params=req_params)
            return _err("CONFLICT", "label is already deleted")

        now = _now()
        label["status"] = "deleted"
        label["updated_at"] = now

        # remove label id from any tasks.label_ids for same connection, same "transaction"
        cleaned = 0
        for t in tasks:
            if t.get("connection_id") != connection_id:
                continue
            lids = t.get("label_ids")
            if not isinstance(lids, list) or not lids:
                continue
            if label_id in lids:
                t["label_ids"] = [x for x in lids if x != label_id]
                t["updated_at"] = now
                cleaned += 1

        _save("todoist_labels.json", labels)
        _save("todoist_tasks.json", tasks)

        _log("succeeded", request_params=req_params)
        return {"label": label, "removed_from_tasks_count": cleaned}
    except Exception as e:
        _log("failed", error_code="failed", error_message=str(e), request_params=req_params)
        return _err("failed", str(e))

