        v = int.from_bytes(b, "big")
        out = ""
        for _ in range(26):
            out = alphabet[v & 31] + out
            v >>= 5
        return f"{prefix}_{out}"

    def _log(status_run, http_status=None, error_code=None, error_message=None, request_params=None):
