        if not isinstance(parent_task_id, str) or not parent_task_id.startswith("tdtsk_"):
            _log("failed", error_code="VALIDATION_ERROR", error_message="parent_task_id is malformed", request_params=req_params)
            return _err("VALIDATION_ERROR", "parent_task_id is malformed")
        if not isinstance(content, str) or not content.strip() or len(content.strip()) > 500:
            _log("failed", error_code="VALIDATION_ERROR", error_message="content must be a non-empty string up to 500 chars", request_params=req_params)
            return _err("VALIDATION_ERROR", "content must be a non-empty string up to 500 chars")
        if description is not None and not isinstance(description, str):
            _log("failed", error_code="VALIDATION_ERROR", error_message="description must be a string", request_params=req_params)
            return _err("VALIDATION_ERROR", "description must be a string")
        if priority is None:
