            return _err("VALIDATION_ERROR", "deadline_at must be an ISO 8601 date-time string")
        if due_timezone is not None and not isinstance(due_timezone, str):
            _log("failed", error_code="VALIDATION_ERROR", error_message="due_timezone must be a string", request_params=req_params)
            return _err("VALIDATION_ERROR", "due_timezone must be a string")
        if due_string_raw is not None and not isinstance(due_string_raw, str):
            _log("failed", error_code="VALIDATION_ERROR", error_message="due_string_raw must be a string", request_params=req_params)
            return _err("VALIDATION_ERROR", "due_string_raw must be a string")

        if label_ids is None:
            label_ids = []
        if not isinstance(label_ids, list) or any(not isinstance(x, str) for x in label_ids):
            _log("failed", error_code="VALIDATION_ERROR", error_message="label_ids must be an array of strings", request_params=req_params)
            return _err("VALIDATION_ERROR", "label_ids must be an array of strings")
        for x in label_ids:
            if not x.startswith("tdlbl_"):
                _log("failed", error_code="VALIDATION_ERROR", error_message="label_ids contains malformed id", request_params=req_params)
                return _err("VALIDATION_ERROR", "label_ids contains malformed id")

        if project_container_id is not None and (not isinstance(project_container_id, str) or not project_container_id.startswith("tdcnb_")):
            _log("failed", error_code="VALIDATION_ERROR", error_message="project_container_id is malformed", request_params=req_params)
            return _err("VALIDATION_ERROR", "project_container_id is malformed")
        if section_container_id is not None and (not isinstance(section_container_id, str) or not section_container_id.startswith("tdcnb_")):
            _log("failed", error_code="VALIDATION_ERROR", error_message="section_container_id is malformed", request_params=req_params)
            return _err("VALIDATION_ERROR", "section_container_id is malformed")

        conns = _load("todoist_connections.json")
        conn = next((c for c in conns if c.get("id") == connection_id), None)
        if not conn or conn.get("status") == "disabled":
            _log("failed", error_code="UNAUTHORIZED", error_message="Connection not accessible", request_params=req_params)
            return _err("UNAUTHORIZED", "Connection not accessible")

        tasks = _load("todoist_tasks.json")
        containers = _load("todoist_containers.json")
        labels = _load("todoist_labels.json")

        parent = next((t for t in tasks if t.get("id") == parent_task_id and t.get("connection_id") == connection_id), None)
        if not parent:
            _log("failed", error_code="NOT_FOUND", error_message="parent task not found", request_params=req_params)
