        if parent.get("status") == "deleted":
            _log("failed", error_code="INVALID_TRANSITION", error_message="Cannot create a subtask under a deleted parent task", request_params=req_params)
            return _err("INVALID_TRANSITION", "Cannot create a subtask under a deleted parent task")

        # default containers to parent's project/section
        effective_project = project_container_id if project_container_id is not None else parent.get("project_container_id")
        effective_section = section_container_id if section_container_id is not None else parent.get("section_container_id")

        # validate containers: cross-connection references rejected
        if effective_project is not None:
            proj = next((c for c in containers if c.get("id") == effective_project and c.get("connection_id") == connection_id), None)
            if not proj or proj.get("type") != "project" or proj.get("status") == "deleted":
                _log("failed", error_code="NOT_FOUND", error_message="project_container_id not found", request_params=req_params)
                return _err("NOT_FOUND", "project_container_id not found")
        if effective_section is not None:
            sec = next((c for c in containers if c.get("id") == effective_section and c.get("connection_id") == connection_id), None)
            if not sec or sec.get("type") != "section" or sec.get("status") == "deleted":
                _log("failed", error_code="NOT_FOUND", error_message="section_container_id not found", request_params=req_params)
                return _err("NOT_FOUND", "section_container_id not found")
            if effective_project is None:
                _log("failed", error_code="VALIDATION_ERROR", error_message="section_container_id provided without a project_container_id context", request_params=req_params)
                return _err("VALIDATION_ERROR", "section_container_id provided without a project_container_id context")
            if sec.get("parent_project_id") != effective_project:
                _log("failed", error_code="VALIDATION_ERROR", error_message="section_container_id does not belong to project_container_id", request_params=req_params)
                return _err("VALIDATION_ERROR", "section_container_id does not belong to project_container_id")

        # validate labels exist and active
        label_map = {l.get("id"): l for l in labels if l.get("connection_id") == connection_id}
        for lid in label_ids:
            if lid not in label_map or label_map[lid].get("status") == "deleted":
                _log("failed", error_code="NOT_FOUND", error_message=f"label_id not found: {lid}", request_params=req_params)
                return _err("NOT_FOUND", f"label_id not found: {lid}")

        now = _now()
        new_task = {
            "id": _gen_id("tdtsk"),
            "connection_id": connection_id,
            "external_id": None,
            "content": content.strip(),
            "description": description,
            "project_container_id": effective_project,
            "section_container_id": effective_section,
            "parent_task_id": parent_task_id,
            "priority": priority,
            "due_date": dd if due_date is not None else None,
            "due_timezone": due_timezone,
            "due_string_raw": due_string_raw,
            "deadline_at": dl if deadline_at is not None else None,
            "label_ids": list(label_ids),
            "status": "active",
            "completed_at": None,
            "deleted_at": None,
            "created_at": now,
            "updated_at": now,
        }
        tasks.append(new_task)
        _save("todoist_tasks.json", tasks)

        _log("succeeded", request_params=req_params)
        return {"task": new_task}
    except Exception as e:
        _log("failed", error_code="failed", error_message=str(e), request_params=req_params)
        return _err("failed", str(e))

