            out = alphabet[v & 31] + out
            v >>= 5
        return f"{prefix}_{out}"

    def _log(status_run, http_status=None, error_code=None, error_message=None, request_params=None):
        runs = _load("todoist_tool_runs.json")
        now = _now()
        dur = max(0, int((time.time() - t0) * 1000))
        runs.append({
            "id": _gen_id("tdrun"),
            "connection_id": connection_id if isinstance(connection_id, str) else "unknown",
            "tool_name": "todoist_task_convert_to_subtask",
            "request_params": request_params,
            "status": status_run,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": dur if status_run in ("succeeded", "failed") else None,
            "assertions": None,
            "created_at": now,
            "updated_at": now,
        })
        _save("todoist_tool_runs.json", runs)

    req_params = {"connection_id": connection_id, "task_id": task_id, "new_parent_task_id": new_parent_task_id}

    try:
        if not isinstance(connection_id, str) or not connection_id.strip() or not connection_id.startswith("tdc_"):
            _log("failed", error_code="VALIDATION_ERROR", error_message="connection_id is malformed", request_params=req_params)
            return _err("VALIDATION_ERROR", "connection_id is malformed")
        if not isinstance(task_id, str) or not task_id.startswith("tdtsk_"):
            _log("failed", error_code="VALIDATION_ERROR", error_message="task_id is malformed", request_params=req_params)
            return _err("VALIDATION_ERROR", "task_id is malformed")
        if not isinstance(new_parent_task_id, str) or not new_parent_task_id.startswith("tdtsk_"):
            _log("failed", error_code="VALIDATION_ERROR", error_message="new_parent_task_id is malformed", request_params=req_params)
            return _err("VALIDATION_ERROR", "new_parent_task_id is malformed")
        if task_id == new_parent_task_id:
            _log("failed", error_code="CONFLICT", error_message="A task cannot be a subtask of itself", request_params=req_params)
            return _err("CONFLICT", "A task cannot be a subtask of itself")

        conns = _load("todoist_connections.json")
        conn = next((c for c in conns if c.get("id") == connection_id), None)
        if not conn or conn.get("status") == "disabled":
            _log("failed", error_code="UNAUTHORIZED", error_message="Connection not accessible", request_params=req_params)
            return _err("UNAUTHORIZED", "Connection not accessible")

        tasks = _load("todoist_tasks.json")
        target = next((t for t in tasks if t.get("id") == task_id and t.get("connection_id") == connection_id), None)
        parent = next((t for t in tasks if t.get("id") == new_parent_task_id and t.get("connection_id") == connection_id), None)
        if not target:
            _log("failed", error_code="NOT_FOUND", error_message="task not found", request_params=req_params)
            return _err("NOT_FOUND", "task not found")
        if not parent:
            _log("failed", error_code="NOT_FOUND", error_message="new parent task not found", request_params=req_params)
            return _err("NOT_FOUND", "new parent task not found")
        if target.get("status") == "deleted":
            _log("failed", error_code="INVALID_TRANSITION", error_message="Cannot move a deleted task under a parent", request_params=req_params)
            return _err("INVALID_TRANSITION", "Cannot move a deleted task under a parent")
        if parent.get("status") == "deleted":
            _log("failed", error_code="INVALID_TRANSITION", error_message="Cannot set a deleted task as parent", request_params=req_params)
            return _err("INVALID_TRANSITION", "Cannot set a deleted task as parent")

        # prevent cycles: parent cannot be target or its descendants
        children_map = {}
        for t in tasks:
            if t.get("connection_id") == connection_id:
                pid = t.get("parent_task_id")
                if isinstance(pid, str) and pid:
                    children_map.setdefault(pid, []).append(t.get("id"))

        def _descendants(root):
            out = set()
            stack = [root]
            while stack:
                cur = stack.pop()
                for ch in children_map.get(cur, []):
                    if ch not in out:
                        out.add(ch)
                        stack.append(ch)
            return out

        desc = _descendants(task_id)
        if new_parent_task_id in desc:
            _log("failed", error_code="CONFLICT", error_message="Conversion would create a cycle (parent is a descendant)", request_params=req_params)
            return _err("CONFLICT", "Conversion would create a cycle (parent is a descendant)")

        # apply update
        target["parent_task_id"] = new_parent_task_id
        target["updated_at"] = _now()
        _save("todoist_tasks.json", tasks)

        _log("succeeded", request_params=req_params)
        return {"task": target}
    except Exception as e:
        _log("failed", error_code="failed", error_message=str(e), request_params=req_params)
        return _err("failed", str(e))

