def todoist_task_hierarchy_get(connection_id, task_id, include_completed=None, include_deleted=None, max_depth=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0360000" if __import__("os").path.isdir("./environment_mix/0360000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _record_run(conn_id, req_params, status, http_status=None, error_code=None, error_message=None, assertions=None):
        runs = _load("todoist_tool_runs.json")
        # generate ULID-like id with correct prefix; randomness is fine offline
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        import random
        def _gen_ulid_like(prefix):
            return prefix + "_" + "".join(random.choice(alphabet) for _ in range(26))
        rid = _gen_ulid_like("tdrun")
        duration_ms = int((time.time() - t0) * 1000)
        row = {
            "id": rid,
            "connection_id": conn_id,
            "tool_name": "todoist_task_hierarchy_get",
            "request_params": req_params,
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": duration_ms if status in ("succeeded", "failed") else None,
            "assertions": assertions,
            "created_at": now,
            "updated_at": now,
        }
        runs.append(row)
        _save("todoist_tool_runs.json", runs)

    # Validate inputs
    if not isinstance(connection_id, str):
        _record_run(connection_id if isinstance(connection_id, str) else "unknown", {"connection_id": connection_id, "task_id": task_id}, "failed", error_code="VALIDATION_ERROR", error_message="connection_id must be a string")
        return _err("VALIDATION_ERROR", "connection_id must be a string")
    if not re.match(r"^tdc_[0-9A-HJKMNP-TV-Z]{26}$", connection_id):
        _record_run(connection_id, {"connection_id": connection_id, "task_id": task_id}, "failed", error_code="VALIDATION_ERROR", error_message="connection_id format is invalid")
        return _err("VALIDATION_ERROR", "connection_id format is invalid")
    if not isinstance(task_id, str):
        _record_run(connection_id, {"connection_id": connection_id, "task_id": task_id}, "failed", error_code="VALIDATION_ERROR", error_message="task_id must be a string")
        return _err("VALIDATION_ERROR", "task_id must be a string")
    if not re.match(r"^tdtsk_[0-9A-HJKMNP-TV-Z]{26}$", task_id):
        _record_run(connection_id, {"connection_id": connection_id, "task_id": task_id}, "failed", error_code="VALIDATION_ERROR", error_message="task_id format is invalid")
        return _err("VALIDATION_ERROR", "task_id format is invalid")
    if include_completed is not None and not isinstance(include_completed, bool):
        _record_run(connection_id, {"connection_id": connection_id, "task_id": task_id}, "failed", error_code="VALIDATION_ERROR", error_message="include_completed must be boolean")
        return _err("VALIDATION_ERROR", "include_completed must be boolean")
    if include_deleted is not None and not isinstance(include_deleted, bool):
        _record_run(connection_id, {"connection_id": connection_id, "task_id": task_id}, "failed", error_code="VALIDATION_ERROR", error_message="include_deleted must be boolean")
        return _err("VALIDATION_ERROR", "include_deleted must be boolean")
    if max_depth is not None:
        if not isinstance(max_depth, int):
            _record_run(connection_id, {"connection_id": connection_id, "task_id": task_id, "max_depth": max_depth}, "failed", error_code="VALIDATION_ERROR", error_message="max_depth must be integer")
            return _err("VALIDATION_ERROR", "max_depth must be integer")
        if max_depth < 1:
            _record_run(connection_id, {"connection_id": connection_id, "task_id": task_id, "max_depth": max_depth}, "failed", error_code="VALIDATION_ERROR", error_message="max_depth must be >= 1")
            return _err("VALIDATION_ERROR", "max_depth must be >= 1")

    include_completed = True if include_completed is None else include_completed
    include_deleted = False if include_deleted is None else include_deleted

    # Auth/context resolution (ambient): require an existing accessible connection row
    conns = _load("todoist_connections.json")
    conn = next((c for c in conns if c.get("id") == connection_id), None)
    if not conn:
        _record_run(connection_id, {"connection_id": connection_id, "task_id": task_id}, "failed", error_code="NOT_FOUND", error_message="Connection not found")
        return _err("NOT_FOUND", "Connection not found")
    if conn.get("status") == "disabled":
        _record_run(connection_id, {"connection_id": connection_id, "task_id": task_id}, "failed", error_code="UNAUTHORIZED", error_message="Connection is disabled")
        return _err("UNAUTHORIZED", "Connection is disabled")

    tasks = _load("todoist_tasks.json")
    by_id = {t.get("id"): t for t in tasks if t.get("connection_id") == connection_id}

    root = by_id.get(task_id)
    if not root:
        _record_run(connection_id, {"connection_id": connection_id, "task_id": task_id}, "failed", error_code="NOT_FOUND", error_message="Task not found")
        return _err("NOT_FOUND", "Task not found")
    if root.get("status") == "deleted" and not include_deleted:
        _record_run(connection_id, {"connection_id": connection_id, "task_id": task_id, "include_deleted": include_deleted}, "failed", error_code="NOT_FOUND", error_message="Task not found")
        return _err("NOT_FOUND", "Task not found")

    # Build children map constrained to connection
    children = {}
    for t in tasks:
        if t.get("connection_id") != connection_id:
            continue
        pid = t.get("parent_task_id")
        if pid:
            children.setdefault(pid, []).append(t)

    def _dt_key(v):
        # ISO8601 sortable; None last
        if not v:
            return ""
        return str(v)

    def _sort_key(t):
        # created_at primary; fallback updated_at then id for determinism
        return (_dt_key(t.get("created_at")), _dt_key(t.get("updated_at")), str(t.get("id") or ""))

    for k in list(children.keys()):
        children[k].sort(key=_sort_key)

    def _allowed(task_row):
        st = task_row.get("status")
        if st == "deleted" and not include_deleted:
            return False
        if st == "completed" and not include_completed:
            return False
        return True

    def _sanitize_task(trow):
        # return task row as stored (no secret fields exist on task)
        return dict(trow)

    def _build(node_id, depth):
        node = by_id.get(node_id)
        if not node:
            return None
        if not _allowed(node) and node_id != task_id:
            return None

        out = {"task": _sanitize_task(node), "subtasks": []}
        if max_depth is not None and depth >= max_depth:
            return out

        for ch in children.get(node_id, []):
            if ch.get("id") not in by_id:
                continue
            built = _build(ch.get("id"), depth + 1)
            if built is not None:
                out["subtasks"].append(built)
        return out

    tree = _build(task_id, 0)

    _record_run(connection_id, {"connection_id": connection_id, "task_id": task_id, "include_completed": include_completed, "include_deleted": include_deleted, "max_depth": max_depth}, "succeeded")
    return {
        "connection_id": connection_id,
        "root_task_id": task_id,
        "include_completed": include_completed,
        "include_deleted": include_deleted,
        "max_depth": max_depth,
        "hierarchy": tree,
    }

