                _ = _load("todoist_tasks.json")
                # emulate lookup
                _ = next((t for t in _ if t.get("id") == fixture_task_id and t.get("connection_id") == connection_id), None)
            elif op == "todoist_project_get":
                _ = _load("todoist_containers.json")
                _ = [c for c in _ if c.get("connection_id") == connection_id and c.get("type") == "project" and c.get("status") != "deleted"]
            elif op == "todoist_label_stats":
                _tasks = _load("todoist_tasks.json")
                _labels = _load("todoist_labels.json")
                active_labels = [l for l in _labels if l.get("connection_id") == connection_id and l.get("status") != "deleted"]
                for l in active_labels:
                    lid = l.get("id")
                    _ = sum(1 for t in _tasks if t.get("connection_id") == connection_id and t.get("status") in ("active", "completed") and isinstance(t.get("label_ids"), list) and lid in t.get("label_ids"))
            elif op == "todoist_task_hierarchy_get":
                _tasks = _load("todoist_tasks.json")
                by_id = {t.get("id"): t for t in _tasks if t.get("connection_id") == connection_id}
                children = {}
                for t in _tasks:
                    if t.get("connection_id") != connection_id: 
                        continue
                    pid = t.get("parent_task_id")
                    if pid:
                        children.setdefault(pid, []).append(t)
                # traverse shallow
                root = by_id.get(fixture_task_id)
                if root:
                    _ = children.get(fixture_task_id, [])
            elif op == "todoist_task_create":
                _tasks = _load("todoist_tasks.json")
                tid = _gen("tdtsk")
                _tasks.append({
                    "id": tid, "connection_id": connection_id, "external_id": None,
                    "content": "Perf Create", "description": None,
                    "project_container_id": None, "section_container_id": None, "parent_task_id": None,
                    "priority": 1, "due_date": None, "due_timezone": None, "due_string_raw": None,
                    "deadline_at": None, "label_ids": [], "status": "active",
                    "completed_at": None, "deleted_at": None, "created_at": now, "updated_at": now
                })
                _save("todoist_tasks.json", _tasks)
                created_ids["task_ids"].append(tid)
            elif op == "todoist_task_update":
                _tasks = _load("todoist_tasks.json")
                t = next((x for x in _tasks if x.get("id") == fixture_task_id and x.get("connection_id") == connection_id), None)
                if t and t.get("status") != "deleted":
                    t["content"] = (t.get("content") or "") + "."
                    t["updated_at"] = now
                    _save("todoist_tasks.json", _tasks)
            elif op == "todoist_task_complete":
                _tasks = _load("todoist_tasks.json")
                t = next((x for x in _tasks if x.get("id") == fixture_task_id and x.get("connection_id") == connection_id), None)
                if t and t.get("status") == "active":
                    t["status"] = "completed"
                    t["completed_at"] = now
                    t["updated_at"] = now
                    _save("todoist_tasks.json", _tasks)
            elif op == "todoist_task_delete":
                _tasks = _load("todoist_tasks.json")
                t = next((x for x in _tasks if x.get("id") == fixture_task_id and x.get("connection_id") == connection_id), None)
                if t and t.get("status") != "deleted":
                    t["status"] = "deleted"
                    t["deleted_at"] = now
                    t["completed_at"] = None if t.get("status") != "completed" else t.get("completed_at")
                    t["updated_at"] = now
                    _save("todoist_tasks.json", _tasks)
            else:
                # For unsupported in offline benchmark: do minimal IO to represent overhead
                _ = _load("todoist_tasks.json")

        # warmups
        for _i in range(warmup_iterations):
            _op_call()

        for _i in range(iterations):
            t1 = time.perf_counter()
            _op_call()
            t2 = time.perf_counter()
            timings.append((t2 - t1) * 1000.0)

        # cleanup created tasks if any (soft delete)
        if created_ids["task_ids"]:
            _tasks = _load("todoist_tasks.json")
            for tid in created_ids["task_ids"]:
                tr = next((x for x in _tasks if x.get("id") == tid and x.get("connection_id") == connection_id), None)
                if tr and tr.get("status") != "deleted":
                    tr["status"] = "deleted"
                    tr["deleted_at"] = now
                    tr["updated_at"] = now
            _save("todoist_tasks.json", _tasks)

        return timings

    for op in operations:
        try:
            times = _measure(op)
            report["operations"][op] = {
                "count": len(times),
                "min_ms": min(times) if times else None,
                "max_ms": max(times) if times else None,
                "mean_ms": statistics.mean(times) if times else None,
                "p50_ms": statistics.median(times) if times else None,
            }
        except Exception as e:
            report["operations"][op] = {"error": str(e)}

    _record_run(connection_id, {"connection_id": connection_id, "iterations": iterations, "warmup_iterations": warmup_iterations, "operations": operations}, "succeeded", http_status=200)
    return report
